INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 1, 5, 1, "ヒヨリ", "どんなに敵が大勢でも、みんなで\n力を合わせれば絶対大丈夫だよ！\nだから顔を上げてこう！\nごーごー！", "", "vo_empress_100101_001", "vo_empress_100101_001", 4, 100101);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 2, 5, 1, "ヒヨリ", "ううっ、何度も戦う相手もいるけど\nあたし、負けたりなんてしないよ！\n今回だってみんなや騎士くんがいる\nフルパワーでいくよーっ！", "", "vo_empress_100101_002", "vo_empress_100101_002", 4, 100103);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 2, "", 3, 5, 1, "ヒヨリ", "うぅ…すごい力…！\n…でも、なんだか悲しそう\nこの人の気持ちを知りたい\nだからこそ…勝たなきゃ…！", "", "vo_empress_100101_003", "vo_empress_100101_003", 4, 100103);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (100101, 3, "", 4, 5, 1, "ヒヨリ", "騎士くんの力があれば、\nあたしは絶対負けないよ！\nみんなが笑顔でいられるように\n一緒にがんばろう！", "", "vo_empress_100101_004", "vo_empress_100101_004", 4, 100102);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 5, 5, 1, "ユイ", "わたしたちの世界のためにも\nこの世界のためにも、\n絶対に負けられない…！\nがんばろうね、騎士クン", "", "vo_empress_100201_001", "vo_empress_100201_001", 4, 100203);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 6, 5, 1, "ユイ", "みんな、怪我したらすぐに教えて！\n…もう誰も失いたくないの\nそのために修行もしたんだから…\n大丈夫、絶対なんとかしてみせる！", "", "vo_empress_100201_002", "vo_empress_100201_002", 4, 100203);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 2, "", 7, 5, 1, "ユイ", "世界を『書き換え』するなんて…\nそんな未来、寂しいだけだよ…！\nお願い、これ以上みんなを\n傷つけないで…話を聞いて！", "", "vo_empress_100201_003", "vo_empress_100201_003", 4, 100203);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (100201, 3, "", 8, 5, 1, "ユイ", "感じるよ、騎士クンの気持ち…\n抱きしめられてるみたいに\nあったかい…\nぜんぶ終わらせよう！", "", "vo_empress_100201_004", "vo_empress_100201_004", 4, 100202);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 9, 5, 1, "レイ", "厳しい戦いになるだろうな\n安心してくれ、何があっても\nキミは守る。…いや、違うな\n一緒に、世界を守ろう", "", "vo_empress_100301_001", "vo_empress_100301_001", 4, 100301);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 10, 5, 1, "レイ", "手ごわい相手ばかりだな…\nだが引き下がるわけにはいかない\nこちらにだって譲れないものが\nあるんだ！", "", "vo_empress_100301_002", "vo_empress_100301_002", 4, 100303);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 2, "", 11, 5, 1, "レイ", "くっ…なんて力だ…！\n防ぐだけで精一杯…だが、\n例え剣が折れたとしても、\n私は最後まで戦い続ける！", "", "vo_empress_100301_003", "vo_empress_100301_003", 4, 100303);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (100301, 3, "", 12, 5, 1, "レイ", "感じるよ、キミからの愛\nこれがあれば、私はどんな\n敵にだって打ち勝てる！\n見せてやろう、一緒に！", "", "vo_empress_100301_004", "vo_empress_100301_004", 4, 100302);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 13, 5, 1, "ミソギ", "ミソギとにいちゃんはこれからも\n世界中を冒険して、ワクワクする\nお宝をたくさん見つけるんだ！\nワルモノなんかに邪魔させないよ！", "", "vo_empress_100401_001", "vo_empress_100401_001", 4, 100401);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 14, 5, 1, "ミソギ", "わわ、なんかヤバそうな雰囲気…\nこういう時こそミソギの出番だね！\nとっておきのイタズラ決めて、\nピンチもひっくり返しちゃうよ！", "", "vo_empress_100401_002", "vo_empress_100401_002", 4, 100401);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 2, "", 15, 5, 1, "ミソギ", "うぅ…あの悪者、すごい迫力だよ…\nもしミソギたちが負けちゃったら、\nミソギもにいちゃんもこの世界も…\n全部おしまい、なんだよね…？", "", "vo_empress_100401_003", "vo_empress_100401_003", 4, 100403);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (100401, 3, "", 16, 5, 1, "ミソギ", "ミソギたちが世界を救っちゃったら\nきっとみんなびっくりするよね！\nどんな顔して驚いてくれるかな…\nにひひ、なんかワクワクしてきた！", "", "vo_empress_100401_004", "vo_empress_100401_004", 4, 100402);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 17, 5, 1, "マツリ", "歴代オールヒーロー大進撃ッス～！\n自分は新世代のエースってとこッス\nかね？　さあ、ついてくるッス……\nあれ？　みんなどこ？　待って～", "", "vo_empress_100501_001", "vo_empress_100501_001", 4, 100501);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 18, 5, 1, "マツリ", "敵は圧倒的な力で、こっちを絶望\nさせる気ッスかね？　だとしたら\n大誤算ッスよ！　むしろ自分の\n正義の魂に火をつけたんスから！", "", "vo_empress_100501_002", "vo_empress_100501_002", 4, 100501);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 2, "", 19, 5, 1, "マツリ", "足が……震えるッス……けど！\nこれは武者震いッス……！　だって\nヒーローは絶対に絶対にっ！\n敗北なんてしないんスから……っ！", "", "vo_empress_100501_003", "vo_empress_100501_003", 4, 100503);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (100501, 3, "", 20, 5, 1, "マツリ", "さあ、手と手をつないで、\n二人で教えてやるッスよ！\nどんな物語でも、悪は必ずヒーロー\nに打ち倒されるってことを！", "", "vo_empress_100501_004", "vo_empress_100501_004", 4, 100502);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 21, 5, 1, "アカリ", "ひゃぁんっ！\nもう、敵さんが脅かしてくるから\nアカリ、ヘンな声出ちゃいました…\nこういうの、よくないですよっ", "", "vo_empress_100601_001", "vo_empress_100601_001", 4, 100603);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 22, 5, 1, "アカリ", "アカリ、お兄ちゃんとシタイコトが\nまだまだいっぱいあるんです！\nだから、私たちの大事な世界も…\n本気で守り抜いてみせますっ！", "", "vo_empress_100601_002", "vo_empress_100601_002", 4, 100601);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 2, "", 23, 5, 1, "アカリ", "うぅ…こんなに激しく攻められたら\nアカリ、もう壊れちゃいそうです…\nだけどまだまだ…戦えますっ！\nお兄ちゃんが一緒なんですからっ…", "", "vo_empress_100601_003", "vo_empress_100601_003", 4, 100603);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (100601, 3, "", 24, 5, 1, "アカリ", "お兄ちゃんの愛を注いでもらって\nアカリ超絶パワーアップです！\nアカリらしく世界一かわいく、\n世界を救ってみせちゃいますよ！", "", "vo_empress_100601_004", "vo_empress_100601_004", 4, 100602);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 25, 5, 1, "ミヤコ", "アイツらが野放しだと、ミヤコは\n安心してプリンを食べられないの\n今日のプリンと明日のプリンの\nためにも、絶対負けないの！", "", "vo_empress_100701_001", "vo_empress_100701_001", 4, 100701);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 26, 5, 1, "ミヤコ", "前はミヤコ、悪いヤツに捕まって\n消されそうになって怖かったの…\nでも今度は全然怖くないの！\nオマエが一緒なら平気なの！", "", "vo_empress_100701_002", "vo_empress_100701_002", 4, 100702);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 2, "", 27, 5, 1, "ミヤコ", "むうぅ～っ、アイツしつこいの！\nこうなったら、オマエにも\nミヤコのプリン分けてやるの！\nダブルプリンパワーで頑張るの！", "", "vo_empress_100701_003", "vo_empress_100701_003", 4, 100703);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (100701, 3, "", 28, 5, 1, "ミヤコ", "アイツはどんなに強くたって、\n独りぼっちのさびしいヤツなの\nでもオマエにはミヤコがいるの！\nミヤコたちなら絶対に勝てるの！", "", "vo_empress_100701_004", "vo_empress_100701_004", 4, 100702);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 29, 5, 1, "ユキ", "相手が誰であれ、やることは同じ…\nそう…ボクの美しさを見せてあげる\nことさ！　予言しよう…絶世の美の\n前にはどんな敵もひれ伏すと、ね！", "", "vo_empress_100801_001", "vo_empress_100801_001", 4, 100801);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 30, 5, 1, "ユキ", "少し待っていてくれる？　メイクを\n直さないと。避けられない戦いなら\nせめて美しいボクと戦えることを\n彼らには誇りに思ってほしいからね", "", "vo_empress_100801_002", "vo_empress_100801_002", 4, 100801);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 2, "", 31, 5, 1, "ユキ", "どうせ倒れるなら美しいままで散り\nたいな。ふふ、難しい望みかな…？\nそれでもボクは、最後まで美しく\nあがいてみせるよ、キミと一緒にね", "", "vo_empress_100801_003", "vo_empress_100801_003", 4, 100801);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (100801, 3, "", 32, 5, 1, "ユキ", "ボクがいて、キミがいる。ボクたち\nが勝つのに、これ以上の理由はない\nよね。だって美しい者が勝つ未来の\nほうが、美しいエンディングだもの", "", "vo_empress_100801_004", "vo_empress_100801_004", 4, 100802);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 33, 5, 1, "アンナ", "災厄の嵐が吹き荒れ、世界の命運は\n風前の灯が如く儚い。だが絶望には\nまだ早い！　希望はここに在り！\n灯火を掲げよう、盟友シグルドよ！", "", "vo_empress_100901_001", "vo_empress_100901_001", 4, 100901);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 34, 5, 1, "アンナ", "終焉の日、滅びの刻来たれり、か…\nだが、幾度も転生を繰り返しながら\n戦いつづけた我らの宿命を思えば、\nこの程度取るに足らない…はずだ！", "", "vo_empress_100901_002", "vo_empress_100901_002", 4, 100903);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 2, "", 35, 5, 1, "アンナ", "くっ…なんという禍々しい魔力…！\nもはや世界の滅びも間近…しかし\n疾風の冥姫がここで退くわけには\nいかぬ！　しぶとく抗ってみせるぞ", "", "vo_empress_100901_003", "vo_empress_100901_003", 4, 100903);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (100901, 3, "", 36, 5, 1, "アンナ", "永遠の盟約で結ばれし魂の伴侶…\n世界を滅ぼさんとする災禍の剣も\nこの絆を断ち切ることはできない！\n覚悟するがいい、幻境竜后！！", "", "vo_empress_100901_004", "vo_empress_100901_004", 4, 100902);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 37, 5, 1, "マホ", "【自警団】のギルドマスターとして\nしゃんとして恥ずかしない姿を\n見せなあきまへんなぁ…王子はん\nしゃなりしゃなり、いきまひょ！", "", "vo_empress_101001_001", "vo_empress_101001_001", 4, 101001);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 38, 5, 1, "マホ", "王子はん、服が破れてますえ？\nこれでよし…うん、完璧や♪\n戦いの中でも、王子はんには\n格好良う居てもらいたいさかいに♪", "", "vo_empress_101001_002", "vo_empress_101001_002", 4, 101001);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 2, "", 39, 5, 1, "マホ", "幻境竜后…大層なお名前してはる\nお后さまが勝負を挑んできはるなら\nうちも、マホマホ王国の姫として…\n正々堂々受けて立ちますえ！", "", "vo_empress_101001_003", "vo_empress_101001_003", 4, 101003);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (101001, 3, "", 40, 5, 1, "マホ", "強い愛で結ばれた王子と姫を\n引き裂くことは誰にもできまへん\n王子はん…ふたりで一緒に！\nハッピーエンドを迎えまひょ！", "", "vo_empress_101001_004", "vo_empress_101001_004", 4, 101002);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 41, 5, 1, "リノ", "お兄ちゃんがいれば百人力士っ！\n妹パワーも全開でいきますよ～♪\nどんな敵でもドンドンこいですっ！\nあれ？　ちょっと違いました？", "", "vo_empress_101101_001", "vo_empress_101101_001", 4, 101101);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 42, 5, 1, "リノ", "これぞまさに『四面そば』…\n敵多すぎでもう大盛りですけど\n秘密結社の一員として、妹として\nこの世界の平和は守り通しますっ！", "", "vo_empress_101101_002", "vo_empress_101101_002", 4, 101101);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 2, "", 43, 5, 1, "リノ", "あれが幻境竜后…不思議な服…\nじゃなくて、空気がピリピリです…\nちょっとだけ怖いけど…妹として\n絶対に降参なんてしませんよ！", "", "vo_empress_101101_003", "vo_empress_101101_003", 4, 101103);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (101101, 3, "", 44, 5, 1, "リノ", "私、もう迷いません！\nお兄ちゃんと一緒なら\nどんな敵だって倒しちゃいます！\n妹のポテンシャルは無限大ですよ！", "", "vo_empress_101101_004", "vo_empress_101101_004", 4, 101102);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 45, 5, 1, "ハツネ", "どんなに大変な時でもキミと一緒に\nず～っと乗り越えてきたんだもん！\nだからっ、今回もきっと大丈夫！\n私の魔法できらーん☆　だよっ！", "", "vo_empress_101201_001", "vo_empress_101201_001", 4, 101201);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 46, 5, 1, "ハツネ", "力を使いすぎると眠く…スヤァ…\nはっ、いけないいけない！\nキミ、私が寝ちゃったら起こして！\n…お、王子様のキスとかで…", "", "vo_empress_101201_002", "vo_empress_101201_002", 4, 101202);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 2, "", 47, 5, 1, "ハツネ", "も～！　容赦なさすぎだよぉ！\nそっ、それにさっきまでの戦いの\nせいで、ね、眠気がぁ～っ…\nハ、ハツネちゃん、ピ～ンチ…", "", "vo_empress_101201_003", "vo_empress_101201_003", 4, 101203);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (101201, 3, "", 48, 5, 1, "ハツネ", "幻境竜后さんがどんなに強くても\n今のハツネちゃんは無敵なのだ～！\n大好きなキミと！　シオリンと！\nみんながいる世界を守っちゃうよ！", "", "vo_empress_101201_004", "vo_empress_101201_004", 4, 101202);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 49, 5, 1, "ナナカ", "この世界にはね、たくさんの人の\n『好き』が詰まってるんだよ\nそれをぶち壊すなんて鬼畜の所業\nナナカちゃんが許しはしないぜ！", "", "vo_empress_101301_001", "vo_empress_101301_001", 4, 101301);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 50, 5, 1, "ナナカ", "見るからにヤバい奴らが勢ぞろい！\nでもみんなの世界が狙われてんのに\n日和ってる奴いる？いねえよなぁ！\n全員ぶっ飛ばして世界を救うぞ！！", "", "vo_empress_101301_002", "vo_empress_101301_002", 4, 101301);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 2, "", 51, 5, 1, "ナナカ", "あとはラスボスを倒せば勝利ッ！\n第３部完！　…とはいかない感じ？\nていうか逆にピンチな気配？\nどっどうしよう、どうすれば！？", "", "vo_empress_101301_003", "vo_empress_101301_003", 4, 101303);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (101301, 3, "", 52, 5, 1, "ナナカ", "幻境竜后…確かに強敵だったね\nでも今はもう負ける気がしないかな\nだって私は、ただのナナカじゃない\n超ナナカちゃんだから…！", "", "vo_empress_101301_004", "vo_empress_101301_004", 4, 101302);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 53, 5, 1, "カスミ", "あちらにもなかなかの陰謀家がいる\nようだね。彼女らの最大の誤算は\nここに希代の名探偵がいることさ！\nさあ助手くん。真実を勝ち取ろう！", "", "vo_empress_101401_001", "vo_empress_101401_001", 4, 101401);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 54, 5, 1, "カスミ", "仕方ない、こうなったら奥の手だ\nミスティ！　セオリー！　…って\nこらぁっ！　変身の最中は待って\nくれるのがお約束だよ！？", "", "vo_empress_101401_002", "vo_empress_101401_002", 4, 101401);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 2, "", 55, 5, 1, "カスミ", "なっ…なんだい、この悪寒は…\n触れてはならない何か…いいや！\n名探偵たるもの巨悪に恐れをなす\nわけにはいかない。絶対に…！", "", "vo_empress_101401_003", "vo_empress_101401_003", 4, 101403);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (101401, 3, "", 56, 5, 1, "カスミ", "どんな哀しみでさえ、道理を穢す\n理由にしてはならない。さあ、\nお縄につくんだ。史上最大の迷宮\n事件…終わらせるのは…この私だ！", "", "vo_empress_101401_004", "vo_empress_101401_004", 4, 101402);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 57, 5, 1, "ミサト", "先生は…ううん、先生たちは。\n絶対に負けません。みんなに傷一つ\nつけさせたりはしないわ…！", "", "vo_empress_101501_001", "vo_empress_101501_001", 4, 101501);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 58, 5, 1, "ミサト", "とっても強大な敵ばかりね…\nでも、大丈夫。焦らず落ち着いて\n戦いましょう。先生がついてるわ\n長引いても、あきらめないで…！", "", "vo_empress_101501_002", "vo_empress_101501_002", 4, 101501);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 2, "", 59, 5, 1, "ミサト", "幻境竜后さんの力…すごいわ…\nううん、怖がってる暇なんてないの\n森のみんなを守るためにも…！\n好き勝手したら「めっ」ですからね", "", "vo_empress_101501_003", "vo_empress_101501_003", 4, 101501);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (101501, 3, "", 60, 5, 1, "ミサト", "あなたと一緒なら\n負けたりなんか絶対にしないわ\n最後の一撃まで、\nがんばりましょうね♪", "", "vo_empress_101501_004", "vo_empress_101501_004", 4, 101502);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 61, 5, 1, "スズナ", "ツヨそーな敵ばっかりで\nテン下げってカンジだけど\nとりま、うちとヒデサイが\n一緒なら乗り越えられるっしょ！", "", "vo_empress_101601_001", "vo_empress_101601_001", 4, 101601);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 62, 5, 1, "スズナ", "あっ、まってヒデサイ\nマントずれてるから直してあげる\n…よし！　こーゆう時こそ\nおしゃれでテン上げしなきゃね♪", "", "vo_empress_101601_002", "vo_empress_101601_002", 4, 101601);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 2, "", 63, 5, 1, "スズナ", "おにヤバすぎて超わろ～…でもでも\nどうにかやるしかないっしょ～\n勝利のランウェイ遠すぎだけど\nうちら諦めんのはダメだよね～！", "", "vo_empress_101601_003", "vo_empress_101601_003", 4, 101601);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (101601, 3, "", 64, 5, 1, "スズナ", "アオハルでバイブス爆上げ♪\n今のうちらは、ムテキだよ～\nハッピーで、もにカワな未来だって\n一緒にゲットするしかないっしょ♪", "", "vo_empress_101601_004", "vo_empress_101601_004", 4, 101602);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 65, 5, 1, "カオリ", "歌ったり踊ったり、\nキミと一緒にやりたいことが\nばんないあるからね～！\n絶対に負けられないさ～！", "", "vo_empress_101701_001", "vo_empress_101701_001", 4, 101701);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 66, 5, 1, "カオリ", "ううっ強そうな敵ばっかりさ～！\n長丁場の戦いにはやっぱりこれよ～\nサーターアンダギー！\n栄養付けて平和を守るさ～♪", "", "vo_empress_101701_002", "vo_empress_101701_002", 4, 101701);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 2, "", 67, 5, 1, "カオリ", "うぅ～、幻境竜后、でーじ強いね～\n私たちも引き下がる気はないよ～！\nどんなに時間がかかっても、絶対に\n諦めたりしないさ～！　だよね～？", "", "vo_empress_101701_003", "vo_empress_101701_003", 4, 101703);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (101701, 3, "", 68, 5, 1, "カオリ", "キミのくれた情熱が、\n私の中で熱く燃え滾ってるよ！\n最高の一撃、キミに見せるさ～！", "", "vo_empress_101701_004", "vo_empress_101701_004", 4, 101702);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 69, 5, 1, "イオ", "学校生活の邪魔はさせないわ\nだって私、みんなの先生だもの\n明日の授業も世界のことも\n全部守ってみせるんだから！", "", "vo_empress_101801_001", "vo_empress_101801_001", 4, 101801);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 70, 5, 1, "イオ", "やん！　なんて手ごわい人たちなの\nでも諦めないわ。難しい問題だって\n落ち着いてやればちゃんと解けるの\n戦いも同じよ…いきましょう！", "", "vo_empress_101801_002", "vo_empress_101801_002", 4, 101801);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 2, "", 71, 5, 1, "イオ", "これが、幻境竜后さんの力…圧倒\nされちゃいそう。でも、怖がってる\n場合じゃないわ。先生は絶対に、\nここから退かないわ！", "", "vo_empress_101801_003", "vo_empress_101801_003", 4, 101803);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (101801, 3, "", 72, 5, 1, "イオ", "二人の絆があれば、\n怖いものなんてないわ\n先生と力を合わせて─\nいきましょう♪", "", "vo_empress_101801_004", "vo_empress_101801_004", 4, 101802);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 73, 5, 1, "ミミ", "す、すごく強そうな人がいっぱい…\nミミ、怖くてぶるぶるしちゃうけど\nでも泣いちゃったりはしないよっ\nおにいちゃんがいっしょだもん…！", "", "vo_empress_102001_001", "vo_empress_102001_001", 4, 102003);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 74, 5, 1, "ミミ", "プチグリフォンさんもハナちゃんも\nみゅ～ちゃんも…きっとみんな、\nミミのこと応援してくれてるよね\nだからミミも、がんばるよっ…！", "", "vo_empress_102001_002", "vo_empress_102001_002", 4, 102003);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 2, "", 75, 5, 1, "ミミ", "あ、あの竜の人…本気になったら、\nすごく強そうだよ…！このままじゃ\nみんなもミミたちも負けちゃう…？\nやだ、ミミそんなのいやだよっ…", "", "vo_empress_102001_003", "vo_empress_102001_003", 4, 102003);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (102001, 3, "", 76, 5, 1, "ミミ", "おにいちゃんがくれた元気、\n今度はミミたちから届けようね\nもう大丈夫、心配しないでって…\n世界中の、大切なお友だちに…！", "", "vo_empress_102001_004", "vo_empress_102001_004", 4, 102002);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 77, 5, 1, "クルミ", "怖い人たちがいっぱいですぅ…！\n…でも、みんな頑張ってる…私も\nベルルちゃんみたいに勇気を出して\n…祝福の音を鳴らしましょう！", "", "vo_empress_102101_001", "vo_empress_102101_001", 4, 102101);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 78, 5, 1, "クルミ", "お兄ちゃん、私、がんばりますぅ\n『ロスト』したお父さんたちの\nためにも…！　怖い時こそ前を見て\n戦ってみせますからっ…！", "", "vo_empress_102101_002", "vo_empress_102101_002", 4, 102101);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 2, "", 79, 5, 1, "クルミ", "っ…すごい迫力ですぅ…！\nでも…絶望は必ず乗り越えられる\n胸の中の、希望の音色を信じて…\n逃げたりなんか、しませんよぅ…っ", "", "vo_empress_102101_003", "vo_empress_102101_003", 4, 102101);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (102101, 3, "", 80, 5, 1, "クルミ", "みんなに勇気を与えるために\n主役にも英雄にもなってみせますぅ\nお兄ちゃんがいてくれるなら\n私はなんでもできるんです…！", "", "vo_empress_102101_004", "vo_empress_102101_004", 4, 102102);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 81, 5, 1, "ヨリ", "こ、これくらいの敵、問題ないわ！\nほんとはちょっと怖いけど…\nゲームの世界を救うことくらい\nこっちは慣れっこなんだから…！", "", "vo_empress_102201_001", "vo_empress_102201_001", 4, 102201);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 82, 5, 1, "ヨリ", "ここで私たちが負けたら、\n世界が終わっちゃうなんて…\n絶対に認めるわけにはいかないわ！\nアンタも覚悟決めなさいよっ！", "", "vo_empress_102201_002", "vo_empress_102201_002", 4, 102201);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 2, "", 83, 5, 1, "ヨリ", "ここからが本当の戦いってこと？\nならもう、とことんやってやるわ！\nゲーマーってのは、敵が手強いほど\n燃えてくる生き物なのよ！", "", "vo_empress_102201_003", "vo_empress_102201_003", 4, 102203);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (102201, 3, "", 84, 5, 1, "ヨリ", "絶対に帰りたい理由ができた…\nそう思うだけで、いくらでも力が\n湧いてくるの。これならもう、\n文句なしの勝ち確よねっ！", "", "vo_empress_102201_004", "vo_empress_102201_004", 4, 102202);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 85, 5, 1, "アヤネ", "私もみんなと一緒に戦うよ！\n悪い人たちはフルスイングで\nあっという間に倒しちゃうから！\n『おうっ！　全員かかってこい！』", "", "vo_empress_102301_001", "vo_empress_102301_001", 4, 102301);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 86, 5, 1, "アヤネ", "本当はちょっとだけ怖いけど…\nぷうきちもお兄ちゃんも一緒だもん\n力を合わせて世界を守っちゃうよ\n絶対に負けないんだから！", "", "vo_empress_102301_002", "vo_empress_102301_002", 4, 102303);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 2, "", 87, 5, 1, "アヤネ", "ううっあの人、すごく怖いけど\n逃げないよ、戦うって決めたもん\nね、お兄ちゃん、ぷうきち！\n『ここが踏ん張りどころだぞ！』", "", "vo_empress_102301_003", "vo_empress_102301_003", 4, 102303);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (102301, 3, "", 88, 5, 1, "アヤネ", "お兄ちゃんが約束してくれたもん\n今の私ならどんな悪いやつにも\n負けないよ！　宇宙人でもなんでも\n一撃で追い返しちゃうんだから♪", "", "vo_empress_102301_004", "vo_empress_102301_004", 4, 102302);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 89, 5, 1, "スズメ", "大変なことになっちゃいましたね…\nで、でも怖がっていられません！\nお嬢さまのことも、あなたのことも\n私が精一杯お支えします！", "", "vo_empress_102501_001", "vo_empress_102501_001", 4, 102503);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 90, 5, 1, "スズメ", "世界の命運がかかってますから\nドジなんてしてられません！\n…って、ああっ！　言ったそばから\nまた魔法が暴走しちゃいましたっ！", "", "vo_empress_102501_002", "vo_empress_102501_002", 4, 102503);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 2, "", 91, 5, 1, "スズメ", "す、すごい力です…！\nでもお嬢さまや大切な人をおいて\n逃げるわけにはいきません！\nどこまでもお供します…！", "", "vo_empress_102501_003", "vo_empress_102501_003", 4, 102503);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (102501, 3, "", 92, 5, 1, "スズメ", "大切な人と力を合わせれば、\nドジな私でも世界を救えるんです！\n世界規模…いえ、宇宙規模の大掃除\n始めちゃいますよ～っ！", "", "vo_empress_102501_004", "vo_empress_102501_004", 4, 102502);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 93, 5, 1, "リン", "ええー？　こんだけ人数いるならさ\n一人ぐらいいなくても…\n…って空気じゃないわけね\nはいはい、あたしも働きますよー", "", "vo_empress_102601_001", "vo_empress_102601_001", 4, 102603);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 94, 5, 1, "リン", "うぅ…あんなのもうバグでしょ！？\nこんな無理ゲーに参戦したんだもん\n終わったらしばらく働かないから！\nダラダラゴロゴロするからね～！", "", "vo_empress_102601_002", "vo_empress_102601_002", 4, 102603);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 2, "", 95, 5, 1, "リン", "見てよあのビジュアルさー\nまさにラスボスって感じじゃん…\nでも、どんなゲームでもボスは\n倒せるわけだし…はぁ、やるかー", "", "vo_empress_102601_003", "vo_empress_102601_003", 4, 102603);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (102601, 3, "", 96, 5, 1, "リン", "ここまで来たら後には退けないし\n正真正銘のラスボス戦ってんなら\nあたしも─気合い入れて\n少しぐらいイイとこ見せないとね！", "", "vo_empress_102601_004", "vo_empress_102601_004", 4, 102602);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 97, 5, 1, "エリコ", "有象無象のクズ虫が、私たちの\n幸せを阻もうとしているようですね\nあぁ、なんて忌々しいのでしょう…\n残らずすり潰しますわ、クスクス…", "", "vo_empress_102701_001", "vo_empress_102701_001", 4, 102701);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 98, 5, 1, "エリコ", "クスクス…あら、失礼しましたわ\nこの連中を駆逐すれば、私たちの\n絆はより強く…そんな想像をしたら\n思わず…クスクスクス、クスクス", "", "vo_empress_102701_002", "vo_empress_102701_002", 4, 102701);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 2, "", 99, 5, 1, "エリコ", "あの女…下らない言葉であなた様を\n誑かそうとしたとか。万死に値する\n罪…身の程を思い知らせてやるまで\n決して退きはしませんわ…", "", "vo_empress_102701_003", "vo_empress_102701_003", 4, 102703);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (102701, 3, "", 100, 5, 1, "エリコ", "『壊し屋』と呼ばれる私ですが…\n今はこの力、創るために振るいます\nあなた様との愛、未来…\nクスクス…さあ参りましょう…♪", "", "vo_empress_102701_004", "vo_empress_102701_004", 4, 102702);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 101, 5, 1, "サレン", "しっかり頭数揃えてきたわね…\nでもこの程度の力に屈するような\nあたしたちじゃないんだから\nあんたも、サポート頼んだわよ！", "", "vo_empress_102801_001", "vo_empress_102801_001", 4, 102801);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 4002, 10000, 102, 3, 1, "サレン", "ちょっと！　なんか向こうに\n教育に悪そうなのがいるんだけど！\nあいつは子どもたちの目に入る前に\nあたしたちで倒すわよ。いい？", 1, "vo_empress_102801_002", "vo_empress_102801_002", 4, 102801);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 2, "", 103, 5, 1, "サレン", "もう、強すぎて参っちゃうわね…\nでも諦めるわけにはいかないわ\nこっちだって守らなきゃいけない\nものがたくさんあるんだから！", "", "vo_empress_102801_003", "vo_empress_102801_003", 4, 102803);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (102801, 3, "", 104, 5, 1, "サレン", "いつも以上に負ける気がしないわ\nこれもあんたと気持ちが通じた\nおかげね。あんたが側にいる限り、\nあたしはずっと無敵なんだから！", "", "vo_empress_102801_004", "vo_empress_102801_004", 4, 102802);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 105, 5, 1, "ノゾミ", "この世界が終わっちゃうって…\nアイドル活動も卒業ってコト！？\nファンのみんなが黙ってないよ！\nもちろん私だって…！", "", "vo_empress_102901_001", "vo_empress_102901_001", 4, 102903);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 106, 5, 1, "ノゾミ", "どんな強い敵にだって屈しない…\n歌って踊って戦うアイドルになる！\nあの日に誓った願い、私の希望！\n今こそ、果たして見せるんだから！", "", "vo_empress_102901_002", "vo_empress_102901_002", 4, 102903);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 2, "", 107, 5, 1, "ノゾミ", "幻境竜后…ダンスも歌も、あなたに\nとって価値はないかもしれないけど\n私はこのステージから逃げたり\nなんてしない！　アイドルとして！", "", "vo_empress_102901_003", "vo_empress_102901_003", 4, 102903);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (102901, 3, "", 108, 5, 1, "ノゾミ", "星を書き換えるなんてすごい発想…\nプロデューサーとか向いてるかも？\nって、今はそんな場合じゃないか！\n覚悟してよね、幻境竜后！", "", "vo_empress_102901_004", "vo_empress_102901_004", 4, 102901);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 109, 5, 1, "ニノン", "ショーグンの天下統一を阻む者は\n誰であろうと許しまセン！\nショーグン！　ここはチューシン\nニノンにお任せアーレー！", "", "vo_empress_103001_001", "vo_empress_103001_001", 4, 103001);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 110, 5, 1, "ニノン", "むむむ…待ち受けているのは強敵\nばかり…それでも退きまセン！\n超烈火之紅蓮旋風で、\nまとめて討ち取ってみせまショウ！", "", "vo_empress_103001_002", "vo_empress_103001_002", 4, 103001);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 2, "", 111, 5, 1, "ニノン", "な、なんて強さ…このままでは、\nワタシたちは負けてしまいます…\n…いいえ。いいえ！　ショーグンの\nためにも、諦めることなど…っ！", "", "vo_empress_103001_003", "vo_empress_103001_003", 4, 103003);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (103001, 3, "", 112, 5, 1, "ニノン", "感じマス、ショーグンの愛を…！\n今ならどんな敵が来ても、\nカッサイ、ボンサイ、\nオチャノコサイサイデース！", "", "vo_empress_103001_004", "vo_empress_103001_004", 4, 103002);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 113, 5, 1, "シノブ", "この世界が、明日を迎えることなく\n滅んでしまうかもしれない…\n運命の岐路が、目の前にあります\n抗えるのは、私たちだけです…！", "", "vo_empress_103101_001", "vo_empress_103101_001", 4, 103101);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 114, 5, 1, "シノブ", "何よりも色濃い死の気配が、\n世界に満ちていくのを感じます\nでも、倒れるわけにはいきません\n最後まで戦いましょう、全力で", "", "vo_empress_103101_002", "vo_empress_103101_002", 4, 103101);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 2, "", 115, 5, 1, "シノブ", "これほどまでに強大な力なんて…\n占いも、未来は滅びの闇に覆われ\nつつある、と出ています…それでも\n希望を手放すわけには…！", "", "vo_empress_103101_003", "vo_empress_103101_003", 4, 103103);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (103101, 3, "", 116, 5, 1, "シノブ", "命ある者にとって、死の運命は\n決して避けられないもの…\nでも、今この時ではないはずです\n戦いましょう、未来のために…！", "", "vo_empress_103101_004", "vo_empress_103101_004", 4, 103101);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 117, 5, 1, "アキノ", "これ以上の狼藉は許しません！\nウィスタリア家の名に懸けて、\nこの世界の人々を守ります…必ずや\n貴人としての役目を果たしますわ！", "", "vo_empress_103201_001", "vo_empress_103201_001", 4, 103201);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 118, 5, 1, "アキノ", "互いを利するウィンウィンの関係\nそれが商売の鉄則です。力を振るい\n一方的に望みを押し付けるなんて、\n倒産まっしぐらですわよっ！", "", "vo_empress_103201_002", "vo_empress_103201_002", 4, 103201);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 2, "", 119, 5, 1, "アキノ", "幻境竜后…すさまじい力ですわね\n世界を意のままにするという野望も\n決して絵空事ではないのでしょう…\nそれでも私は…諦めませんわよ！", "", "vo_empress_103201_003", "vo_empress_103201_003", 4, 103203);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (103201, 3, "", 120, 5, 1, "アキノ", "人々を守ることが力ある者の務め…\nそしてあなたさまと共に生きること\nそれが私の務めであり願いですわ！\nこの想いは、止まりませんわよ！", "", "vo_empress_103201_004", "vo_empress_103201_004", 4, 103202);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 121, 5, 1, "マヒル", "こんな舞台で漫才したって\nみんなもお天道さんもどんよりだべ\n安心して笑ってられる世界を\nオラたちで取り戻すど！　おー！", "", "vo_empress_103301_001", "vo_empress_103301_001", 4, 103301);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 122, 5, 1, "マヒル", "お、おっかねぇ連中だ…！\nでも…スベっちまう怖さに比べりゃ\nマシだべな！　あははっ！\nみんなの笑顔は、オラが守るべ！", "", "vo_empress_103301_002", "vo_empress_103301_002", 4, 103301);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 2, "", 123, 5, 1, "マヒル", "あの子、芸人として光りそうだべな\n幻境竜后なんて仰々しい名前も…\nノーヴィジョンズノープロブレム！\n…あたた！　激しいツッコミだべ！", "", "vo_empress_103301_003", "vo_empress_103301_003", 4, 103303);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (103301, 3, "", 124, 5, 1, "マヒル", "逆境も笑顔で切り開く…\nあんちゃんと一緒なら\nできる気がすんだ\nオラたちの芸人魂、見せてやるべ！", "", "vo_empress_103301_004", "vo_empress_103301_004", 4, 103302);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 125, 5, 1, "ユカリ", "元…ううん、正しき聖騎士として\nここでやらなきゃいつやるのよ…！\n必ずみんなを守りきってみせるわ\n怪我をした人は私のところへ！", "", "vo_empress_103401_001", "vo_empress_103401_001", 4, 103401);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 126, 5, 1, "ユカリ", "…んぐっ…ごくっ…ぷは～っ♪\nよぉし気合十分らわ～っ！\nこら～幻境竜后～っ！　隠れて\nないでかかってきなさ～い！", "", "vo_empress_103401_002", "vo_empress_103401_002", 4, 103401);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 2, "", 127, 5, 1, "ユカリ", "ひっく…ふぇ？　な、なに……？\nと、とっても大きいのが見えりゅ…\n…なっ、なによこれえぇぇ！\nこ、これが幻境竜后の姿なのぉ～っ", "", "vo_empress_103401_003", "vo_empress_103401_003", 4, 103403);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (103401, 3, "", 128, 5, 1, "ユカリ", "私は無敵らのよ～♪　この世界と\nキミと築く\n素敵な未来のために…幻境竜后！\nぶっとばしてやるわぁ～っ！", "", "vo_empress_103401_004", "vo_empress_103401_004", 4, 103402);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 129, 5, 1, "キョウカ", "ここで私たちが諦めたら、このまま\n世界が終わっちゃう！　そんなの\n絶対ダメです！　負けられません！\n私たちで全部退治しちゃいますよ！", "", "vo_empress_103601_001", "vo_empress_103601_001", 4, 103603);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 130, 5, 1, "キョウカ", "うぅ、ふしんしゃがいっぱいです！\n…でも、このくらいへっちゃらです\nお母さんが心配する前に、早く\n片付けておうちに帰りましょう！", "", "vo_empress_103601_002", "vo_empress_103601_002", 4, 103603);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 2, "", 131, 5, 1, "キョウカ", "あれが私たちの敵、幻境竜后…\nほ、本当に勝てるんでしょうか…？\n立ってるだけで体が震えて…でも、\n弱気になっちゃダメですよねっ…！", "", "vo_empress_103601_003", "vo_empress_103601_003", 4, 103601);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (103601, 3, "", 132, 5, 1, "キョウカ", "正直に言うと…まだ少し怖いです\n我慢したって怖くて体が震えます\nでも、あなたがいてくれるから…\n勇気だって同じくらい湧いてきます", "", "vo_empress_103601_004", "vo_empress_103601_004", 4, 103602);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 133, 5, 1, "トモ", "滅ぼすための力に、守るための力が\n屈するわけにはいかないよ。\nこの剣の誇りに賭けて、必ず止める\nさあ、来い！　ミクマ流が相手だ！", "", "vo_empress_103701_001", "vo_empress_103701_001", 4, 103701);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 134, 5, 1, "トモ", "追いかけっこでもしようか\n鬼さんこちら♪　…って、まだ\n来るの！？　不意打ちされる側に\nなるのは趣味じゃないんだけどな！", "", "vo_empress_103701_002", "vo_empress_103701_002", 4, 103701);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 2, "", 135, 5, 1, "トモ", "踏み込めない…踏み込む隙がない…\n向きあってるだけで精一杯なんて…\nで、でも…こんなところで\n剣を捨てるわけにはっ…！", "", "vo_empress_103701_003", "vo_empress_103701_003", 4, 103701);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (103701, 3, "", 136, 5, 1, "トモ", "勝機は私の中にあったんだ…！\nあなたとの、\n一番強くて絶対に消えない絆\nそれが、あいつを倒す力をくれる！", "", "vo_empress_103701_004", "vo_empress_103701_004", 4, 103702);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 137, 5, 1, "シオリ", "手ごわい相手ですね…\nでも、不思議と怖くありません\nあなたと力を合わせれば\n何とかなるって信じていますから", "", "vo_empress_103801_001", "vo_empress_103801_001", 4, 103801);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 138, 5, 1, "シオリ", "あなたの応援で、私の胸に\n愛と希望が満ち溢れています…\n今こそ魔法狩人ピュアリー★シオリ\nに大変身する時なのかも…？", "", "vo_empress_103801_002", "vo_empress_103801_002", 4, 103801);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 2, "", 139, 5, 1, "シオリ", "とてつもない力ですね…\nでも、諦めたくありません\n何度だって立ち上がってみせます\n今までと同じように…！", "", "vo_empress_103801_003", "vo_empress_103801_003", 4, 103803);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (103801, 3, "", 140, 5, 1, "シオリ", "今の私に怖いものなんてありません\nあなたとの愛の力がありますから♪\n…少し舞い上がり過ぎですかね？\nふふ、気を引き締めてがんばります", "", "vo_empress_103801_004", "vo_empress_103801_004", 4, 103802);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 141, 5, 1, "アオイ", "進んで目立ちたくはないですけど…\nと、ともっ…友達を守るためなら！\nＢＢ団として、勇気を振り絞って…\n団長さんと一緒に戦います！", "", "vo_empress_104001_001", "vo_empress_104001_001", 4, 104001);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 142, 5, 1, "アオイ", "いいい、一緒に戦う仲間がこんなに\nいてくれるなんて、こ、心強いの\n助太郎～っ！　私も末席で参加し…\nじゃなくてっ！　全力で戦います！", "", "vo_empress_104001_002", "vo_empress_104001_002", 4, 104002);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 2, "", 143, 5, 1, "アオイ", "ううっ、手も足も声も震えてます…\nで、でも逃げも隠れもしませんよっ\n逃げたらぼっちが廃ります！", "", "vo_empress_104001_003", "vo_empress_104001_003", 4, 104003);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (104001, 3, "", 144, 5, 1, "アオイ", "私はひとりぼっちじゃない…\n団長さんと繋がった絆があるから\nどんな敵だって怖くないですっ！\n行きましょう、団長さんっ！", "", "vo_empress_104001_004", "vo_empress_104001_004", 4, 104002);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 145, 5, 1, "チカ", "やめてくれる気はなさそうです\nそれなら私も、絶対にここを\n動きはしません…！　だって\n私は……ワガママですからっ！", "", "vo_empress_104201_001", "vo_empress_104201_001", 4, 104203);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 146, 5, 1, "チカ", "私の唱喚術は人を守るためのもの…\nこの世界の森羅万象を護るための\nもの。今こそ、声の限り歌います\nこの子たちと、あなたと共に！", "", "vo_empress_104201_002", "vo_empress_104201_002", 4, 104201);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 2, "", 147, 5, 1, "チカ", "精霊たちが震えてる…今までの\n敵とは訳が違うってことですよね…\n私もここに立っているのが精一杯…\n怖いけど…でも！　退きません…！", "", "vo_empress_104201_003", "vo_empress_104201_003", 4, 104203);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (104201, 3, "", 148, 5, 1, "チカ", "今なら歌える気がします。ずっと\n探していた、誰かの心を震わせる歌\n幻境竜后…孤独なあなたの心にも\n私たちの歌が届くように…！", "", "vo_empress_104201_004", "vo_empress_104201_004", 4, 104201);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 149, 5, 1, "マコト", "敵さんがどんだけ強くったって\n後には退けねぇんだ！　そうだろ、\nさぁ、覚悟しやがれよ！", "", "vo_empress_104301_001", "vo_empress_104301_001", 4, 104301);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 150, 5, 1, "マコト", "くっ、敵の連中、ずいぶんな戦力\n揃えてきやがった。けど、\n数でも気合でも負けやしねぇ！\nあたしが嚙み砕いてやる！", "", "vo_empress_104301_002", "vo_empress_104301_002", 4, 104301);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 2, "", 151, 5, 1, "マコト", "幻境竜后とやら…マジで\n洒落になんねえな。だからって\n引き下がるわけにゃいかねえ！\n持ちこたえてやるぜ！", "", "vo_empress_104301_003", "vo_empress_104301_003", 4, 104303);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (104301, 3, "", 152, 5, 1, "マコト", "どんな強い敵でも\n恐れる必要なんてないよな\nさあ、いっしょに─最大パワーで\nブチのめしてやろうぜっ！", "", "vo_empress_104301_004", "vo_empress_104301_004", 4, 104302);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 153, 5, 1, "イリヤ", "ここはいずれわらわが支配する世界\nつまり、わが領地に等しきもの…\n奴らのような不届き者の蛮行、\n見過ごすわけにはいかぬわ！", "", "vo_empress_104401_001", "vo_empress_104401_001", 4, 104401);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 154, 5, 1, "イリヤ", "厳しい戦いになりそうじゃな…\nお主もわらわから離れるでないぞ\nも、もちろん、大人の姿を保つのに\n都合がいいからというだけじゃ！", "", "vo_empress_104401_002", "vo_empress_104401_002", 4, 104401);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 2, "", 155, 5, 1, "イリヤ", "何とも恐ろしく禍々しい力じゃ…\nだが、我が意志は決して挫けぬ\n高貴なる吸血鬼の誇りに懸けて、\n最後まで戦い抜いてみせようぞ", "", "vo_empress_104401_003", "vo_empress_104401_003", 4, 104401);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (104401, 3, "", 156, 5, 1, "イリヤ", "己が誰を敵に回したのかを、\n骨の髄まで知らしめてやろうぞ\nここにいるのは固き絆で結ばれし\n伝説の吸血鬼とその眷属じゃ！", "", "vo_empress_104401_004", "vo_empress_104401_004", 4, 104401);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 157, 5, 1, "クウカ", "とっても強そうな敵ですっ…\n当然、攻撃も強烈になるはず…\nドＳさん、ここはどうかクウカに、\n先頭をお任せください！　ぐふふ♪", "", "vo_empress_104501_001", "vo_empress_104501_001", 4, 104501);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 158, 5, 1, "クウカ", "安心してドＳさんに虐げてもらう\nためにもクウカは負けられませんっ\nこの世界で一番のドＭとして、\n全力で責められに行ってきますっ！", "", "vo_empress_104501_002", "vo_empress_104501_002", 4, 104501);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 2, "", 159, 5, 1, "クウカ", "ううっ、刺激が強すぎますよ…っ\nだけど、ドＭのプライドにかけて\nここで退くわけにはいきませんっ！\nドＳさんのこと、守り抜きます…っ", "", "vo_empress_104501_003", "vo_empress_104501_003", 4, 104503);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (104501, 3, "", 160, 5, 1, "クウカ", "その視線は、『全部終わったらたっ\nぷり調教してやるからな』という\n意味ですね！　ぐふふっ…♪　負け\nられない理由がまた一つできました", "", "vo_empress_104501_004", "vo_empress_104501_004", 4, 104502);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 161, 5, 1, "タマキ", "強そうなやつらが目白押しにゃ～\n短期戦でどうにかならないなら…\n長丁場に向けて、特別価格の\nたい焼きはいかがかにゃ～？", "", "vo_empress_104601_001", "vo_empress_104601_001", 4, 104601);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 162, 5, 1, "タマキ", "ファントムキャッツは\n狙った獲物を逃がさないにゃ！\nあたしたちの未来を手に入れるまで\nとことんやってやるにゃ～！", "", "vo_empress_104601_002", "vo_empress_104601_002", 4, 104601);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 2, "", 163, 5, 1, "タマキ", "にゃにゃっ、これが幻境竜后…\nとんでもない力だにゃ\nでも、ここで逃げたらファントム\nキャッツの名が廃るにゃ～！", "", "vo_empress_104601_003", "vo_empress_104601_003", 4, 104603);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (104601, 3, "", 164, 5, 1, "タマキ", "ファントムキャッツにかかれば\nどんなに強い悪党でも\n滅びる運命にゃ！\nとっておきの一撃、キメるにゃ～！", "", "vo_empress_104601_004", "vo_empress_104601_004", 4, 104602);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 165, 5, 1, "ジュン", "全軍展開！　敵の一体たりとも\nこの先へは進ませるな\n苦しいときは、私の背中を見るんだ\n我々は決して折れはしない！", "", "vo_empress_104701_001", "vo_empress_104701_001", 4, 104701);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 166, 5, 1, "ジュン", "少年…\n最前線は危険だが、下がるつもりは\nないのか？　ふふ、やはり強情だな\nならば、私の隣を絶対に離れるな", "", "vo_empress_104701_002", "vo_empress_104701_002", 4, 104701);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 2, "", 167, 5, 1, "ジュン", "な…なんだ…この冷たい闘気は…！\nみんな、いったん退がれ！\n安心しろ、ここは私が防ぎきる\n…たとえ…この身に代えても", "", "vo_empress_104701_003", "vo_empress_104701_003", 4, 104701);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (104701, 3, "", 168, 5, 1, "ジュン", "幻境竜后、貴様は絶対に勝てないよ\n自分の身以上に、大切な誰かを\n守りたいという、人間の持つ尊い\n想いを、知ることのない貴様は…！", "", "vo_empress_104701_004", "vo_empress_104701_004", 4, 104701);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 169, 5, 1, "ミフユ", "バイト仲間とこの世界のみんなを\n守るために！　私たちのやるべき\nことはただ一つ！　いいわね？\n─最高の効率で倒すわよ！", "", "vo_empress_104801_001", "vo_empress_104801_001", 4, 104801);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 170, 5, 1, "ミフユ", "相手も数が多いし、短期決戦とは\nいかないわね…って！　早く\n勝たなきゃバイトに遅刻しちゃう\nもっと効率アップしていくわよ！", "", "vo_empress_104801_002", "vo_empress_104801_002", 4, 104801);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 2, "", 171, 5, 1, "ミフユ", "幻境竜后……本当に圧倒的な力ね\nだからってそう簡単に諦められる\nわけはないわよね。たとえそれが\n非効率的な判断だとしても……！", "", "vo_empress_104801_003", "vo_empress_104801_003", 4, 104803);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (104801, 3, "", 172, 5, 1, "ミフユ", "こんなに迂遠で非効率的な計画を\n立てる敵になんて負けないわ！\n効率を極めた私たちの一撃を\n叩きつけてやりましょう！", "", "vo_empress_104801_004", "vo_empress_104801_004", 4, 104802);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 173, 5, 1, "シズル", "安心していいよ、弟くん♪\n弟くんには指一本触れさせない！\n絶対に弟くんを守るから…だって\nそれがお姉ちゃんの役目だもんね！", "", "vo_empress_104901_001", "vo_empress_104901_001", 4, 104902);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 174, 5, 1, "シズル", "準備はできてる、弟くん？\n不安なら手をつないであげよっか？\n大丈夫、お姉ちゃんと弟くんなら\n悪いやつらを全部倒せるはず♪", "", "vo_empress_104901_002", "vo_empress_104901_002", 4, 104902);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 2, "", 175, 5, 1, "シズル", "幻境竜后…手強そうだね…\nでも諦めないよ、絶対に！\n弟くんとお姉ちゃんの大切な世界\nきっと守り抜いてみせるんだから！", "", "vo_empress_104901_003", "vo_empress_104901_003", 4, 104903);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (104901, 3, "", 176, 5, 1, "シズル", "お姉ちゃんと弟くんの力を合わせて\n二人の未来を、みんなの未来を\n一緒に守ろっ！　あ、終わったら\nたくさん甘えさせてあげるからね♪", "", "vo_empress_104901_004", "vo_empress_104901_004", 4, 104902);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 177, 5, 1, "ミサキ", "アブナイキレイなお姉さんはね\n『ふれーばー』だから許されるの！\nこんなメチャクチャにするなんて…\n本物の大人のレディが勝負よ勝負！", "", "vo_empress_105001_001", "vo_empress_105001_001", 4, 105001);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 178, 5, 1, "ミサキ", "アタシは全世界代表の\n大人のレディなんだから！\nアンタ！\nしっかりエスコートしてよね！", "", "vo_empress_105001_002", "vo_empress_105001_002", 4, 105001);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 2, "", 179, 5, 1, "ミサキ", "コ、コイツが幻境竜后…っ\n…正直怖いけど…絶対に逃げないわ\n大人のレディのプライドにかけて\n戦い抜いてやるんだから…！", "", "vo_empress_105001_003", "vo_empress_105001_003", 4, 105003);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (105001, 3, "", 180, 5, 1, "ミサキ", "終わったらデートよ！　だって…\n約束があった方がやる気出るもん♪\nよーし！　大人のレディとして\n最後はエレガントに決めるわよ！", "", "vo_empress_105001_004", "vo_empress_105001_004", 4, 105002);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 181, 5, 1, "ミツキ", "なんて重圧かしら…でも、あいにく\n私も伊達に修羅場をくぐってないの\nさあ、かかってきなさい！\n裏の人生経験、見せてあげるわ…♪", "", "vo_empress_105101_001", "vo_empress_105101_001", 4, 105101);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 182, 5, 1, "ミツキ", "私は闇医者である前に科学者なの\nあなたたち、実験に協力してくれる\nわよね？　隻眼の悪魔の名は\n伊達じゃないのよ？　覚悟しなさい", "", "vo_empress_105101_002", "vo_empress_105101_002", 4, 105101);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 2, "", 183, 5, 1, "ミツキ", "到底不可能に思える挑戦こそ\n科学者の腕の見せどころなのよ\n青い薔薇のごとく、人の信念が\n起こす奇跡を見せてあげるわ…！", "", "vo_empress_105101_003", "vo_empress_105101_003", 4, 105101);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (105101, 3, "", 184, 5, 1, "ミツキ", "迷いのない言葉をもらったんだもの\n私だってもう、覚悟を決めたわ\nこの先の未来を君と生きていく…\nそのために全力をぶつけるだけよ！", "", "vo_empress_105101_004", "vo_empress_105101_004", 4, 105101);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 185, 5, 1, "リマ", "私のお友達をいじめるなら\n相手になるわ！\nたとえ魔物に間違えられても\n絶対にここを引かないから！", "", "vo_empress_105201_001", "vo_empress_105201_001", 4, 105201);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 4002, 10000, 186, 3, 1, "リマ", "ね、ねぇ…\nちょっと聞きたいんだけど\n毛皮もないのにあの姿なのよね？\n風邪引いたりしないのかしら？", 1, "vo_empress_105201_002", "vo_empress_105201_002", 4, 105201);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 2, "", 187, 5, 1, "リマ", "ひづめは割れちゃいそうだし…\n毛並みだってボロボロだし…\nでも後ろには彼がいるんだもの\n恋する乙女の負けられない戦いよ！", "", "vo_empress_105201_003", "vo_empress_105201_003", 4, 105201);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (105201, 3, "", 188, 5, 1, "リマ", "私はもう恋する女の子じゃないわ…\n王子様の愛を受け取ったお姫様よ！\n彼が私を守ってくれるように\n私が彼を守ってみせるわ！", "", "vo_empress_105201_004", "vo_empress_105201_004", 4, 105202);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 189, 5, 1, "モニカ", "どれほど強大な敵であろうと、\n我々【ヴァイスフリューゲル\nランドソル支部】がいれば安心…\nこら！　皆纏まって行動しろー！", "", "vo_empress_105301_001", "vo_empress_105301_001", 4, 105303);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 190, 5, 1, "モニカ", "敵戦力は強大無比…だが、\n私たちなら必ず倒せるはずだ！\n白き翼の名のもとに、今こそ\n正義の鉄槌を下してやる！", "", "vo_empress_105301_002", "vo_empress_105301_002", 4, 105301);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 2, "", 191, 5, 1, "モニカ", "これが幻境竜后の底力か…\n名にし負う圧倒的な強さだな…\nだが！　長期戦になろうとも必ずや\n私たちが勝利の旗を掲げるのだ！", "", "vo_empress_105301_003", "vo_empress_105301_003", 4, 105301);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (105301, 3, "", 192, 5, 1, "モニカ", "貴公と一緒ならば\nなんだってできるとも\nさあ、最後の一撃を加えてやろう！", "", "vo_empress_105301_004", "vo_empress_105301_004", 4, 105302);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 193, 5, 1, "ツムギ", "強そうな相手ばかりですけど\nだからなんだっていうんですか！\nほら、騎士さんも気合い入れて！\n一緒に戦いますよ！", "", "vo_empress_105401_001", "vo_empress_105401_001", 4, 105401);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 4002, 10000, 194, 3, 1, "ツムギ", "なんか敵に下着姿…っていうか\nほぼ裸みたいな人いません？\n…え？　あれ趣味なんですか？\nあの人の？　…正気ですか？", 1, "vo_empress_105401_002", "vo_empress_105401_002", 4, 105403);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 2, "", 195, 5, 1, "ツムギ", "世界を作り変えようなんて\n幻境竜后、絶対許せません…！\nあとその服！　そんなに破いて！\nデザイナーが泣いてますよ！", "", "vo_empress_105401_003", "vo_empress_105401_003", 4, 105403);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (105401, 3, "", 196, 5, 1, "ツムギ", "私と騎士さんの糸は\n絶対に切れません！\nだから…今ここで\nすべてを終わらせましょう！", "", "vo_empress_105401_004", "vo_empress_105401_004", 4, 105401);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 197, 5, 1, "アユミ", "つ、強そうな人たちばっかり…\n逃げたいくらいだけど、\nそれはダメ。先輩をケガさせない\nためにも、私も頑張らなくちゃ！", "", "vo_empress_105501_001", "vo_empress_105501_001", 4, 105503);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 198, 5, 1, "アユミ", "私なんかが大それたことを言うのは\n笑われるかも…でも…！\n先輩を守るために、\n世界を守ってみせます…！", "", "vo_empress_105501_002", "vo_empress_105501_002", 4, 105501);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 2, "", 199, 5, 1, "アユミ", "な、なんて大きさ、存在感…！\nまるで私とは真逆の人…\nこうして立ってるだけで、\n私、消えちゃいそうです～っ…！", "", "vo_empress_105501_003", "vo_empress_105501_003", 4, 105503);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (105501, 3, "", 200, 5, 1, "アユミ", "先輩がそばにいてくれる…\nそれだけで勇気が湧いてきて\n前へ進む力がもらえるんです\n行きましょう、先輩！", "", "vo_empress_105501_004", "vo_empress_105501_004", 4, 105502);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 201, 5, 1, "ルカ", "雁首並べてよくもまあ…\nこりゃ長丁場になりそうだ\n釣りと同じくじっくり腰を据えて\n勝負しようじゃないか", "", "vo_empress_105601_001", "vo_empress_105601_001", 4, 105601);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 202, 5, 1, "ルカ", "世界の危機とあっちゃあ\nアタシたち黄昏時の住人でも\n黙っちゃいられないね！\nひとっ働きさせてもらおうかい！", "", "vo_empress_105601_002", "vo_empress_105601_002", 4, 105601);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 2, "", 203, 5, 1, "ルカ", "へぇ、これが幻境竜后かい…\nたいそうな強さだけど、アタシも\nここで退くわけにはいかないんだ\n心に差した刃に懸けて、いくよ！", "", "vo_empress_105601_003", "vo_empress_105601_003", 4, 105603);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (105601, 3, "", 204, 5, 1, "ルカ", "刀も恋も揃ったアタシは天下無双！\nお前さんが側にいてくれれば、\nどんな巨悪にだって勝てるよ！", "", "vo_empress_105601_004", "vo_empress_105601_004", 4, 105602);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 205, 5, 1, "ペコリーヌ", "また一緒に、みんなで\nおいしいごはんを食べるために！\nわたしたちは、絶対に負けません！", "", "vo_empress_105801_001", "vo_empress_105801_001", 4, 105803);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 4003, 10000, 206, 3, 1, "ペコリーヌ", "フレイヤさんだけじゃなく、\n覇瞳皇帝やミロクまで！\n長丁場になりそうです…\n栄養補給はしっかりしましょうね！", 1, "vo_empress_105801_002", "vo_empress_105801_002", 4, 105801);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 2, "", 207, 5, 1, "ペコリーヌ", "これが、幻境竜后の力…\nやばいですね。正直、どうやって\n止めればいいのか分かりません\nでもここで引き下がるわけには…っ", "", "vo_empress_105801_003", "vo_empress_105801_003", 4, 105803);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (105801, 3, "", 208, 5, 1, "ペコリーヌ", "あなたの愛情でお腹いっぱいの\n無敵ペコリーヌ参上です☆\nわたしたちの明日を、この世界を\n全力全開で取り戻しましょう！", "", "vo_empress_105801_004", "vo_empress_105801_004", 4, 105802);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 209, 5, 1, "コッコロ", "みなさまとのおいしいごはんのため\n負けるわけにはまいりません\n主さま、お背中はお任せください\nわたくしがお守りいたします！", "", "vo_empress_105901_001", "vo_empress_105901_001", 4, 105903);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 210, 5, 1, "コッコロ", "敵は強大…ですが、心強い仲間の\nみなさまが一緒でございます\n…全員主さまとお知り合いなのは\n未だに信じられませんが…", "", "vo_empress_105901_002", "vo_empress_105901_002", 4, 105905);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 2, "", 211, 5, 1, "コッコロ", "まだこのような力が…！？\n主さま、ここはお下がりください\nたとえこの身に何があろうと、\nあなただけはお守りいたします…！", "", "vo_empress_105901_003", "vo_empress_105901_003", 4, 105903);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (105901, 3, "", 212, 5, 1, "コッコロ", "主さまとの絆がある限り\nわたくしは絶対に負けません！\nいついかなるときも、何があろうと\nわたくしが導いてみせます！", "", "vo_empress_105901_004", "vo_empress_105901_004", 4, 105902);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 4005, 10000, 213, 3, 1, "キャル", "また陛下と戦うのね…大丈夫、一番\n大事なものが何なのかは分かってる\n…だから、あたしも負けないわ\n─陛下、よろしくお願いします！", 1, "vo_empress_106001_001", "vo_empress_106001_001", 4, 106001);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 214, 5, 1, "キャル", "この世界を好き勝手しようだなんて\nそういう連中に人生振り回されるの\nこちとらもううんざりなのよ！\n全員ぶっ飛ばしてやるんだから！", "", "vo_empress_106001_002", "vo_empress_106001_002", 4, 106003);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 2, "", 215, 5, 1, "キャル", "なんなのよあの力、反則でしょ…\nだけどさ、どんなに怖くたって\nあたしはここから退かないわ\n他に行くとこも、ないんだからっ…", "", "vo_empress_106001_003", "vo_empress_106001_003", 4, 106003);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (106001, 3, "", 216, 5, 1, "キャル", "絆の力でパワーアップ、なんて\nガラじゃないと思ってたけど…\n今だけは調子に乗らせてもらうわ\nもう負ける気がしないってねっ！", "", "vo_empress_106001_004", "vo_empress_106001_004", 4, 106002);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 217, 5, 1, "ノウェム", "晶に直してもらって\n天楼覇断剣も新品同然だ！\n気合い入れていくぞオクトー！\nはーっはっはっはー！", "", "vo_empress_106101_001", "vo_empress_106101_001", 4, 106102);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 218, 5, 1, "ノウェム", "真那、覚悟しとけよ！\nオマエが積み上げてきた悪事…\nこの大悪党がまとめて\nぶっ壊してやるからな！", "", "vo_empress_106101_002", "vo_empress_106101_002", 4, 106101);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 2, "", 219, 5, 1, "ノウェム", "今までの借り…ここでまとめて\n返してやるって、決めてたんだ\nオマエだけは絶対に、許さない\n…オマエが、どれだけ強くても…っ", "", "vo_empress_106101_003", "vo_empress_106101_003", 4, 106103);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (106101, 3, "", 220, 5, 1, "ノウェム", "大悪党のプリンセス？\nなんだかよくわからないけど──\nとにかく、あの化け物ぶった斬りに\n行くぞ！　ついてこい！", "", "vo_empress_106101_004", "vo_empress_106101_004", 4, 106102);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 221, 5, 1, "シェフィ", "絶対に負けられない戦いね\nおいしいごはんと、本当の\nハッピーエンドのために\n気を引き締めていきましょう", "", "vo_empress_106401_001", "vo_empress_106401_001", 4, 106401);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 4004, 10000, 222, 3, 1, "シェフィ", "ミロク…まだ生きていたのね…！\nあの男は私が相手するわ\n兄さんの分もまとめて、\n今ここで借りを返さないと！", 1, "vo_empress_106401_002", "vo_empress_106401_002", 4, 106403);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 2, "", 223, 5, 1, "シェフィ", "こんな力を隠してたなんて…！\n…まだよ。まだ諦めないわ\nどんな方法を使ってでも\nみんなだけは助けてみせる…！", "", "vo_empress_106401_003", "vo_empress_106401_003", 4, 106401);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (106401, 3, "", 224, 5, 1, "シェフィ", "不思議ね…あなたとの思い出で\n全身に力が満ちていくような気持ち\n…私たちが紡いできた絆を\n幻境竜后に見せてやりましょう", "", "vo_empress_106401_004", "vo_empress_106401_004", 4, 106402);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 225, 5, 1, "カヤ", "おまえら、ケンカ売りたいんだろ？\nこの世界そのものに！\nならこっち向けよ。喧嘩屋のオレが\nまとめて買ってやるぜ！", "", "vo_empress_106501_001", "vo_empress_106501_001", 4, 106501);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 226, 5, 1, "カヤ", "オレがドラゴン族なのも、\nこんな力を持ってるのも…きっと\n今日、この時のためだったんだ\nそうだろ？", "", "vo_empress_106501_002", "vo_empress_106501_002", 4, 106501);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 2, "", 227, 5, 1, "カヤ", "ウソだろ…オレが竦んじまってる…\nアイツのあの赤い眼から、眼を\nそらすんじゃねぇ…！　ドラゴン族\nのケンカ最強は…オレ様だろッ…！", "", "vo_empress_106501_003", "vo_empress_106501_003", 4, 106503);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (106501, 3, "", 228, 5, 1, "カヤ", "自分の力に、ずっとビビッてた\nでも今は何よりこの力を頼もしく\n感じるぜ。テメェをぶっ倒し…\n明日を迎えるための力がなァ！", "", "vo_empress_106501_004", "vo_empress_106501_004", 4, 106501);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 229, 5, 1, "イノリ", "どきやがれです！　最強ギャングが\nおまえのシマ分捕りにきたですよ！\nこんだけ仲間がいりゃ楽勝ですね♪\n尻尾巻いて逃げ出しやがれです！！", "", "vo_empress_106601_001", "vo_empress_106601_001", 4, 106603);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 230, 5, 1, "イノリ", "あっちもゾロゾロつれてきやがり\nましたね…へんっ、このあたしが\nビビビビるとでもおお思うですか\n…お、お兄さん、どどどこです？", "", "vo_empress_106601_002", "vo_empress_106601_002", 4, 106601);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 2, "", 231, 5, 1, "イノリ", "…！　あたしと同じドラゴン族？\nボスをプリンセスナイトに従えて\nたとか…へんっ、信じねーです！\nまあボスより性悪そ…ぴゃああっ", "", "vo_empress_106601_003", "vo_empress_106601_003", 4, 106603);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (106601, 3, "", 232, 5, 1, "イノリ", "ふっふっふ～ん！　熱い力が\nどんどん溢れてくるですよっ！\nさあ、懲らしめてやるですっ！\nおしりペンペンですよ！", "", "vo_empress_106601_004", "vo_empress_106601_004", 4, 106602);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 233, 5, 1, "ホマレ", "ふふっ、強そうな子がいっぱいだね\nそれじゃあ、誰が一番か決めよっか\nヴィーちゃんのプリンセスナイトで\n歴代最強は誰なのかを、ね♪", "", "vo_empress_106701_001", "vo_empress_106701_001", 4, 106701);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 234, 5, 1, "ホマレ", "ヴィーちゃんてば、そんな子たちと\n一緒にいるほうが楽しいんだ～？\nじゃ、私たちも見せつけないとだね\n遠慮なくやっちゃおう☆　あははっ", "", "vo_empress_106701_002", "vo_empress_106701_002", 4, 106701);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 2, "", 235, 5, 1, "ホマレ", "これが、ヴィーちゃんの本気…\nとってもとってもすごいなぁ\n怖がりだからこそ、そんなに\n強くなれちゃったのかな…", "", "vo_empress_106701_003", "vo_empress_106701_003", 4, 106703);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (106701, 3, "", 236, 5, 1, "ホマレ", "残念だけど、ヴィーちゃん…\nもうゲームオーバーみたいだよ\nあなたとのどんなゲームも私には…\n全部ドキドキして、楽しかったな", "", "vo_empress_106701_004", "vo_empress_106701_004", 4, 106702);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 237, 5, 1, "ラビリスタ", "毎度、予想を超える困難ばかり\n押し寄せてくるんだからさ～\nま、アタシと少年が居る以上、\n好きにはさせないよ、ってね！", "", "vo_empress_106801_001", "vo_empress_106801_001", 4, 106802);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 4005, 10000, 238, 3, 1, "ラビリスタ", "よりによって真那まで相手かぁ…\nこりゃ一筋縄じゃいかなそうだ\n誰に対応するかは任せるけど、\n真那を相手取るなら頼ってよ", 1, "vo_empress_106801_002", "vo_empress_106801_002", 4, 106801);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 2, "", 239, 5, 1, "ラビリスタ", "当然、奥の手も用意してくるよね\n次から次へと用意周到だこと…\nとはいえこっちも負けられない\nこの難局の突破口を探すとしよう！", "", "vo_empress_106801_003", "vo_empress_106801_003", 4, 106801);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (106801, 3, "", 240, 5, 1, "ラビリスタ", "七冠…しかも幻境竜后が相手なら\n手は抜けそうにもないね\nはは、でもアタシたちならきっと\n乗り越えられーる！　だよね少年♪", "", "vo_empress_106801_004", "vo_empress_106801_004", 4, 106802);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 4005, 10000, 241, 3, 1, "ネネカ", "真那…ふふ、こんなところで相対\nすることになるとは。いつぞやの\n借り、返してあげますよ。用意は\nいいですね？　マサキも、貴方も", 1, "vo_empress_107001_001", "vo_empress_107001_001", 4, 107001);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 242, 5, 1, "ネネカ", "数で私たちを圧倒しようなど…\n底の浅い戦略ですね。返り討ちに\nしてあげましょう…この世界を\nまだ失うわけにはいきませんから", "", "vo_empress_107001_002", "vo_empress_107001_002", 4, 107001);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 2, "", 243, 5, 1, "ネネカ", "この力…計算外ではありますが\nそれは予想外という意味では\nありません。ええ、楽しみましょう\n不可能を解く、方程式の探求を", "", "vo_empress_107001_003", "vo_empress_107001_003", 4, 107001);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (107001, 3, "", 244, 5, 1, "ネネカ", "特等席で観察させてもらいましょう\n貴方の『心』という変数が\n『レジェンドオブアストルム』に\nどのような影響を与えるのかを…", "", "vo_empress_107001_004", "vo_empress_107001_004", 4, 107002);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 245, 5, 1, "クリスティーナ", "クリスティーナさんのご登場だよ☆\nあっははは……☆　またとない宴だ\n心行くまで愉しもうじゃあないか\n血で血を洗うダンス…滾るな♪", "", "vo_empress_107101_001", "vo_empress_107101_001", 4, 107101);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 4005, 10000, 246, 3, 1, "クリスティーナ", "真那さまがお出ましか…ワタシは\n本当に運がいいと見える♪　本気で\n刃を交える機会が巡ってくるなど\n願ってもない幸運だよ☆", 1, "vo_empress_107101_002", "vo_empress_107101_002", 4, 107101);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 2, "", 247, 5, 1, "クリスティーナ", "…ここで退くなど興冷めだろう？\nたとえ足が竦んだとしても…退屈に\n食われるよりもよほどいい！\n最後まで愉しみつくしてやるさ…☆", "", "vo_empress_107101_003", "vo_empress_107101_003", 4, 107103);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (107101, 3, "", 248, 5, 1, "クリスティーナ", "誤算だったなあ、『幻境竜后』\n他の者ならいざ知らず…\nキサマを殺せる唯一の力\n手にしたのはこの『誓約女君』だ！", "", "vo_empress_107101_004", "vo_empress_107101_004", 4, 107102);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 249, 5, 1, "クロエ", "ざーす。世界を救う系の光バイトで\n来たんすけど…あ、説明とかは\n大丈夫っす。慣れてるんでノリで\n入れます─おのれ世界の敵め！", "", "vo_empress_110801_001", "vo_empress_110801_001", 4, 110801);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 4005, 10000, 250, 3, 1, "クロエ", "なっつ、狐のねえさんいるじゃん\nまだ現役で悪モンやってたんだ\nてか中ボスポジに降格してるくね？\n世界の敵界隈、意外とせちがれーな", 1, "vo_empress_110801_002", "vo_empress_110801_002", 4, 110801);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 2, "", 251, 5, 1, "クロエ", "なんかヤベーの出てきたな…\nこのカンジ、若干最悪っていうか\nぶっちゃけ流れ変わったくない？\nこっから捲るのは…結構ダルいわ", "", "vo_empress_110801_003", "vo_empress_110801_003", 4, 110803);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (110801, 3, "", 252, 5, 1, "クロエ", "ちょ、聞いて敵、ウケんだけど\nなんかうち主人公だったみたいだわ\n山場でヒロインに力託され系のやつ\nてわけで、勝ち確いただきでーす", "", "vo_empress_110801_004", "vo_empress_110801_004", 4, 110802);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 253, 5, 1, "チエル", "ちぇるーん☆　ボス敵のみんな～！\n初めまして＆お久しブリリアント！\n世界の美少女ちえるんでっす！\n今からぼっこぼこにしてあげるね！", "", "vo_empress_110901_001", "vo_empress_110901_001", 4, 110901);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 254, 5, 1, "チエル", "クリスＰの敵はカルミナの敵！\nカルミナの敵はなかよし部の敵！\nツアー全通めざして戦います！\n現場の平和はチエルが守る！", "", "vo_empress_110901_002", "vo_empress_110901_002", 4, 110901);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 2, "", 255, 5, 1, "チエル", "あ、あのう…ヤバくないです？\n敵のねえさん、急に年末歌合戦の\nラスボス衣装みたくなりましたけど\nえ、どーしよ…揚げます白旗？", "", "vo_empress_110901_003", "vo_empress_110901_003", 4, 110903);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (110901, 3, "", 256, 5, 1, "チエル", "世界の敵さん、ごめんちゃい！\nなんか愛だか絆だかの超理論的な\nアレでチエル覚醒しちゃいました！\nちぇるっと終わらせてあげますね！", "", "vo_empress_110901_004", "vo_empress_110901_004", 4, 110902);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 257, 5, 1, "ユニ", "世界の危機だって？　何度目だね？\nざまあみろだよ、勝手に滅べば…\nなに、地球の危機？　この箱庭の\n話ではなく？　何ソレ一大事！", "", "vo_empress_111001_001", "vo_empress_111001_001", 4, 111001);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 258, 5, 1, "ユニ", "お、おい…敵が多すぎないか…？\n端の方でわちゃわちゃしてるだけの\n数合わせ要員として来たのだが…\nどういう事だ、聞いてた話と違うぞ", "", "vo_empress_111001_002", "vo_empress_111001_002", 4, 111001);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 2, "", 259, 5, 1, "ユニ", "あばば…なんだ、あの奇怪な姿は…\nあれが理系をこじらせた者の末路か\n宇宙暗黒理系女…どうしてあんなに\nなるまで放っておいたんだ…", "", "vo_empress_111001_003", "vo_empress_111001_003", 4, 111003);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (111001, 3, "", 260, 5, 1, "ユニ", "はん、驕ったな理系の女王よ\n世界は君が思うほど四角くない\n高機能計算機の弾いた数字ごときで\nぼくと彼の行間までは測れまいよ！", "", "vo_empress_111001_004", "vo_empress_111001_004", 4, 111002);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 261, 5, 1, "クレジッタ", "ですからわたくしは商人で、\n戦いなどは不向き…などと\n言ってる場合ではありませんわね！\n参りますわよ、我が陛下のために！", "", "vo_empress_118001_001", "vo_empress_118001_001", 4, 118001);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 262, 5, 1, "クレジッタ", "ああもうはあもう、あっちこっち\n滅茶苦茶にしてくださってからに！\n復興費用の賠償はどなたに\n請求すればよろしいのかしら！？", "", "vo_empress_118001_002", "vo_empress_118001_002", 4, 118003);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 2, "", 263, 5, 1, "クレジッタ", "でっか！？　でっっっっか！！！\n幻境竜后でしたかしら！？\nなんなんですのあの高層建築な方、\n建築基準法違反ですわよ～っ！？", "", "vo_empress_118001_003", "vo_empress_118001_003", 4, 118003);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (118001, 3, "", 264, 5, 1, "クレジッタ", "ホーッホッホッホ！　幻境竜后さん\n貴方にはいらっしゃるのかしら！\n利害でなくその理想のために\n命を賭ける、真実の忠臣が！", "", "vo_empress_118001_004", "vo_empress_118001_004", 4, 118002);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 265, 5, 1, "ランファ", "恐ろしくて強そうな音が…たくさん\nでも…きっと、大丈夫。あなたや、\nミソラちゃん…みんなが一緒で…\nあたたかい音も、たくさんだもの…", "", "vo_empress_118101_001", "vo_empress_118101_001", 4, 118101);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 266, 5, 1, "ランファ", "緊張、してる…？　そ、それなら、\nわたしに、任せて…わたし、歌を、\n歌うわね…聴けばきっと、いつも\n通りの力を、出せると思うから…", "", "vo_empress_118101_002", "vo_empress_118101_002", 4, 118101);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 2, "", 267, 5, 1, "ランファ", "お、音と声が、すごい…\nなんて…なんて恐ろしいのかしら…\n…？　で、でも…この音。\n幻境竜后も、恐怖…している…？", "", "vo_empress_118101_003", "vo_empress_118101_003", 4, 118103);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (118101, 3, "", 268, 5, 1, "ランファ", "わたしの歌が、どれほど役立つかは\nわからない…そ、それでもっ、\nあなたの力になりたいの…だから\nわたし、精一杯、歌うわね…", "", "vo_empress_118101_004", "vo_empress_118101_004", 4, 118102);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 4005, 10000, 269, 3, 1, "ミソラ", "わー、ミロクさんや覇瞳皇帝さんも\nいるじゃないですか★\nそれじゃあわたしのガトリングで\nご挨拶といきましょっか♪", 1, "vo_empress_118201_001", "vo_empress_118201_001", 4, 118201);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 270, 5, 1, "ミソラ", "騎士さんと力を合わせればどんな\n敵もほにゃららら～★　って感じで\nなんとかなると思うんですよねー\nほら、主人公補正ってやつで♪", "", "vo_empress_118201_002", "vo_empress_118201_002", 4, 118201);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 2, "", 271, 5, 1, "ミソラ", "復讐って、イイコトですかね？\n悪いコトですかね？まぁとりあえず\nぶっ壊してから考えましょうか\nね、幻境竜后さん─", "", "vo_empress_118201_003", "vo_empress_118201_003", 4, 118202);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (118201, 3, "", 272, 5, 1, "ミソラ", "騎士さんに選んでもらっちゃいまし\nたし、いらない縁とはバイバイした\nいんですよねー♪　ってわけで、\nここで終わりにさせてもらいます★", "", "vo_empress_118201_004", "vo_empress_118201_004", 4, 118202);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 273, 5, 1, "カリン", "みなさんの力を信じて、\n私も全力でサポートします\n連携と創意工夫があれば、きっと\nこの難局も乗り越えられます！", "", "vo_empress_118501_001", "vo_empress_118501_001", 4, 118501);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 274, 5, 1, "カリン", "過去最大級の強敵が現れました！\nギルド管理協会を代表して…\nあなたに討伐を依頼します！\n報酬はお望みのままに、ですよ♪", "", "vo_empress_118501_002", "vo_empress_118501_002", 4, 118502);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 2, "", 275, 5, 1, "カリン", "…っ。さすがの強敵ですね…\nだからこそ、焦りは禁物…です\nあらゆる事態を想定して、ギルドの\nみなさんを支援するのが私の仕事…", "", "vo_empress_118501_003", "vo_empress_118501_003", 4, 118503);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (118501, 3, "", 276, 5, 1, "カリン", "あなたと共に進めば\nどんな壁も越えられます\n私の、大切な人の無事を信じて…\n今こそ全力を尽くします！", "", "vo_empress_118501_004", "vo_empress_118501_004", 4, 118502);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 277, 5, 1, "ネビア", "あんな奴らを野放しにしてたら\nこの世界が滅茶苦茶にされちゃう！\nでもまぁこれはこれでチャンスよ♪\n最っ高の悪戯の標的にしてあげる！", "", "vo_empress_118601_001", "vo_empress_118601_001", 4, 118601);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 278, 5, 1, "ネビア", "私はただのガイド妖精、みんなに\n比べれば大した力も持ってない…\nでも悪戯妖精なりの意地があんのよ\nあいつらに一泡吹かせてやるわ♪", "", "vo_empress_118601_002", "vo_empress_118601_002", 4, 118601);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 2, "", 279, 5, 1, "ネビア", "幻境竜后、なんて力の持ち主なの\n正直きっついわ…でもまだやれる\n私はデータよ、壊れたって\nあんたを守る壁くらいにはなれる…", "", "vo_empress_118601_003", "vo_empress_118601_003", 4, 118603);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (118601, 3, "", 280, 5, 1, "ネビア", "覚悟しなさいっ！\n出来損ないの悪戯妖精をなめたら\n痛い目に遭うって教えてあげる\nさぁ、最高のショーの始まりよ！", "", "vo_empress_118601_004", "vo_empress_118601_004", 4, 118602);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 281, 5, 1, "ヴァンピィ", "むー！　いたずらっこの暴れんぼ\nさんたちは、ヴァンピィちゃんが\nきつーくおしおきしちゃうよ！\n真祖のおつとめですから！", "", "vo_empress_122301_001", "vo_empress_122301_001", 4, 122303);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 282, 5, 1, "ヴァンピィ", "けんぞくはヴァンピィちゃんの\n背中に隠れてなさいっ。え？\n背中を守りたい？　うん、それなら\nよろしい！　一緒だよ、けんぞく！", "", "vo_empress_122301_002", "vo_empress_122301_002", 4, 122302);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 2, "", 283, 5, 1, "ヴァンピィ", "幻境竜后？　ふーんだ！\nベスちゃんのほーが、ずーっと\n強くてカッコいいですし！\nいくよっ、けんぞくぅ！", "", "vo_empress_122301_003", "vo_empress_122301_003", 4, 122303);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (122301, 3, "", 284, 5, 1, "ヴァンピィ", "ここはみんなの『いばしょ』！\n壊しちゃうなんて、許さないもん\nヴァンピィちゃん、本気で怒ったよ\nやっちゃうよ、けんぞく！", "", "vo_empress_122301_004", "vo_empress_122301_004", 4, 122302);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 285, 5, 1, "アメス", "ほら、あんたは余計な心配しないの\nあいつらに好き勝手させないように\n全力でぶつかっていくだけよ\nあたしたちの未来のためにね♪", "", "vo_empress_123001_001", "vo_empress_123001_001", 4, 123002);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 286, 5, 1, "アメス", "…あの連中も強くてやばいけど…\n一番やばいのは、こんなにたくさん\n女の子の知り合いがいる\nあんたかもしれないわね…", "", "vo_empress_123001_002", "vo_empress_123001_002", 4, 123001);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 2, "", 287, 5, 1, "アメス", "なんて相手なの…さすがに想定を\n超えてるわよ…こんなの卑怯よね\nだからってここで逃げやしないわよ\nせめて、あんたを守るくらいは…！", "", "vo_empress_123001_003", "vo_empress_123001_003", 4, 123003);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (123001, 3, "", 288, 5, 1, "アメス", "敵がどれだけ強くたって関係ないわ\nあんたの行く道はあたしが照らす\n迷ったらあたしを見なさい\nどこまでだって導いてあげる！", "", "vo_empress_123001_004", "vo_empress_123001_004", 4, 123002);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 289, 5, 1, "ネア", "『レギオンウォー』思い出すな～\nあん時は敵側だったけどー\n今回は騎士きゅんたちの隣で\nネアおねえちゃんもがんばるぞ～♡", "", "vo_empress_123301_001", "vo_empress_123301_001", 4, 123301);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 290, 5, 1, "ネア", "だる～、激ヤバなテキばっかじゃん\n騎士きゅんパワー充電しねーと\nおねえちゃんもギリギリかもー\nとりま、ちゅっちゅ♡　してい？", "", "vo_empress_123301_002", "vo_empress_123301_002", 4, 123301);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 2, "", 291, 5, 1, "ネア", "激ヤバドラゴン、ガチしんどー…\nま、だからって負ける気ねーけど\nこーゆう時こそ、スライムの\n粘り強さの見せ所っしょ～　ね♪", "", "vo_empress_123301_003", "vo_empress_123301_003", 4, 123303);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (123301, 3, "", 292, 5, 1, "ネア", "ンフフフフ～♪　今のアタシ、\n騎士きゅんと一心同体ってやつ～？\nめちゃめちゃアガるわ～♪\n愛の力パねぇ～♡", "", "vo_empress_123301_004", "vo_empress_123301_004", 4, 123302);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 293, 5, 1, "クローチェ", "ビーッ！　ビーッ！\nあっちもこっちもそっちも\n強そうな人たちでいっぱいですっ！\nセンサーが壊れちゃいそう～っ！", "", "vo_empress_126401_001", "vo_empress_126401_001", 4, 126401);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 294, 5, 1, "クローチェ", "世界が大変なことになってますっ！\nでもわたしたちは今までだって、\n大変な戦いを乗り越えてきましたっ\nきっと…ううん、絶対勝てますっ！", "", "vo_empress_126401_002", "vo_empress_126401_002", 4, 126401);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 2, "", 295, 5, 1, "クローチェ", "ビビービビビーッ！　…ひゃあっ！\nセンサーが壊れちゃいました…！\nしかも、照準が震えちゃって…\n…これが…この感情が、恐怖…？", "", "vo_empress_126401_003", "vo_empress_126401_003", 4, 126403);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (126401, 3, "", 296, 5, 1, "クローチェ", "今のわたしたちに、怖いものなんて\nありませんっ！　敵さんがどんなに\n強くても…わたしとナイトさんの\n特別なパワーは、もっと強いです！", "", "vo_empress_126401_004", "vo_empress_126401_004", 4, 126402);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 297, 5, 1, "ライラエル", "ジオ・テオゴニアの姫として\nこの星に生きる一個として\nこれ以上の蹂躙を許すわけには\nいきません。そうですね？　騎士", "", "vo_empress_126501_001", "vo_empress_126501_001", 4, 126501);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 4002, 10000, 298, 3, 1, "ライラエル", "穢らわしい、色狂いの山羊めが\n我が従僕を傀儡としてくれた借り、\n兆倍──否、京倍にして\n返してくれようぞ。崩雷夜天！", 1, "vo_empress_126501_002", "vo_empress_126501_002", 4, 126506);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 2, "", 299, 5, 1, "ライラエル", "幻境竜后。迷いなく、圧倒的な力で\nわたしたちの調和を滅しようとする\nそんな力を、認めたくはないのに…\nなんて、困難な戦いなのでしょう…", "", "vo_empress_126501_003", "vo_empress_126501_003", 4, 126503);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (126501, 3, "", 300, 5, 1, "ライラエル", "この星には、あなたがいる…\n悪辣な侵略者と戦う理由など、\nただそれだけで十分です\n守りましょう。わたしたちの世界を", "", "vo_empress_126501_004", "vo_empress_126501_004", 4, 126502);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 4002, 10000, 301, 3, 1, "リンド", "あそこにヴルムを傷つけた人が…！\n…騎士さん、絶対勝ちましょうね\nあの人たちのやったこと、私\n絶対ぜったい許しませんから！", 1, "vo_empress_127701_001", "vo_empress_127701_001", 4, 127701);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 302, 5, 1, "リンド", "騎士さんたちと出会えたこの世界を\n悪いことになんか使わせません\n作り物だなんて信じられませんけど\n失っちゃいけないものはわかります", "", "vo_empress_127701_002", "vo_empress_127701_002", 4, 127701);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 2, "", 303, 5, 1, "リンド", "まだこんな力が残ってるの…！？\n考えなきゃ、私にできること…\n何か…何かないの…！？\nまた私、何もできないの…？", "", "vo_empress_127701_003", "vo_empress_127701_003", 4, 127703);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (127701, 3, "", 304, 5, 1, "リンド", "あなたが側にいてくれるから、\n私もこうして戦えます\nチョロいって言われてもいいです\n私にとって、大切なひとですから", "", "vo_empress_127701_004", "vo_empress_127701_004", 4, 127702);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 305, 5, 1, "ヴルム", "…正直、サボりとかじゃなくて…\nぜんぜん身体はきついです。でも…\n姉貴やみんなと過ごすこの世界は\n誰にも壊させやしませんから…！", "", "vo_empress_127801_001", "vo_empress_127801_001", 4, 127801);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 4002, 10000, 306, 3, 1, "ヴルム", "騎士さん…アルシャトのこと\nあたしにも一発殴らせてください\nふざけた真似してくれたお礼…\n倍にして返してやりますよ", 1, "vo_empress_127801_002", "vo_empress_127801_002", 4, 127801);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 2, "", 307, 5, 1, "ヴルム", "冗談きついです、こんなの…\n勝てっこないじゃないですか\nあたしだってドラゴン族なのに\nこれほどまでに差があるだなんて…", "", "vo_empress_127801_003", "vo_empress_127801_003", 4, 127803);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (127801, 3, "", 308, 5, 1, "ヴルム", "もう後先考えずにいきますよ\n面倒見てくれる人がここにいるので\nあたしと騎士さんが揃えば\n無敵だってとこ見せてやります", "", "vo_empress_127801_004", "vo_empress_127801_004", 4, 127802);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 4005, 10000, 309, 3, 1, "エリス", "覇瞳皇帝…わたしの邪魔をするなら\nかつてのように、消去するだけ\nミロクも…わたしを草野優衣の\n複製と呼んだこと、後悔させてやる", 1, "vo_empress_129001_001", "vo_empress_129001_001", 4, 129001);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 310, 5, 1, "エリス", "管理者の座は失っても\nわたしの意志は揺らがない…\n騎士クンの物語を紡ぐために…\nそれが、わたしの全てだから", "", "vo_empress_129001_002", "vo_empress_129001_002", 4, 129001);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 2, "", 311, 5, 1, "エリス", "これが七冠、幻境竜后の全力…\n管理者だったかつてのわたしを、\n超えるほどの脅威…でも、\n騎士クンだけは、守ってみせる…", "", "vo_empress_129001_003", "vo_empress_129001_003", 4, 129003);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (129001, 3, "", 312, 5, 1, "エリス", "孤独も絶望も越えてきた\nもうどんな闇にも迷わない\n騎士クンが隣にいる限り\nわたしは、負けない", "", "vo_empress_129001_004", "vo_empress_129001_004", 4, 129002);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 313, 5, 1, "アネモネ", "リアを──媛を、傷つけたひとたち\n笑ってられるのも今だけです──\nアルラウネの棘の鋭さ、\n教えてあげますから──", "", "vo_empress_129601_001", "vo_empress_129601_001", 4, 129601);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 314, 5, 1, "アネモネ", "騎士のひと──背中は、任せます\n貴方のこと、\n媛と同じくらい、信じてるので──\n自分でも、びっくりですけど", "", "vo_empress_129601_002", "vo_empress_129601_002", 4, 129601);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 2, "", 315, 5, 1, "アネモネ", "私、ずっと抗ってきたんです\nそのために、強くなったはず──\nだから──諦めたく、ないです…", "", "vo_empress_129601_003", "vo_empress_129601_003", 4, 129603);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (129601, 3, "", 316, 5, 1, "アネモネ", "体が熱くて、思考がまとまらなくて\nなのに負ける気がしない──なんて\nよくわからないです。どうしてか、\n後で教えてください──騎士のひと", "", "vo_empress_129601_004", "vo_empress_129601_004", 4, 129601);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 317, 5, 1, "ネフィ＝ネラ", "難敵強敵揃い踏みなれど\nわっちらが退く理はありんせん\n騎士殿や、手を携えて此度の争乱\n鎮めて見せましょう也", "", "vo_empress_129701_001", "vo_empress_129701_001", 4, 129701);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 318, 5, 1, "ネフィ＝ネラ", "今のわっちが萎弱であろうとて\n貴様等如き梟悪に斃される訳には\nゆかぬ也。再び足甲を舐めさせ\n地に臥すまで仕置きを致しんしょう", "", "vo_empress_129701_002", "vo_empress_129701_002", 4, 129701);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 2, "", 319, 5, 1, "ネフィ＝ネラ", "我が矜持『不退転』─如何なる敵で\nあろうとも揺らぐ仕儀はなし。斯様\nな邪竜程度、退けむと思い侍りしが\n─難儀な由、残念至極─…", "", "vo_empress_129701_003", "vo_empress_129701_003", 4, 129703);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (129701, 3, "", 320, 5, 1, "ネフィ＝ネラ", "参りまする也、騎士殿や\n懼るること等何一つ御座りんせん\n唯わっちらの勇儀を以て、此の星の\n明日を再び…掌中に致しんしょう", "", "vo_empress_129701_004", "vo_empress_129701_004", 4, 129702);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 4003, 10000, 321, 3, 1, "ヤマト", "─おや、フレイヤじゃないか\nずいぶん様変わりしたようだが\n今の方がアタシとしちゃ好みだね\nお礼参りのしがいもあるってもんさ", 1, "vo_empress_130001_001", "vo_empress_130001_001", 4, 130001);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 322, 5, 1, "ヤマト", "…フゥン？　あっちもこっちも\n『王家の装備』を持ってるらしいね\n宝の山ってのはこのことかい\nまとめて搔っ攫ってやろうかね…！", "", "vo_empress_130001_002", "vo_empress_130001_002", 4, 130001);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 2, "", 323, 5, 1, "ヤマト", "ちっ…、幻境竜后つったかい\n世界を奪おうってのも冗談じゃ\nなさそうだ。…ワカナ、フブキ…\nお前たちだけでも、逃げな…", "", "vo_empress_130001_003", "vo_empress_130001_003", 4, 130003);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (130001, 3, "", 324, 5, 1, "ヤマト", "アタシらの住み家を奪おうだぁ？\nハッ、笑わせてくれるね\n盗賊は盗むモンであって、\n盗まれるモンじゃあないンだよ！", "", "vo_empress_130001_004", "vo_empress_130001_004", 4, 130002);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 325, 5, 1, "ワカナ", "つ、強そうな人たちがたくさん…\nなのに姉さんもフブキちゃんも\nやる気満々だし…\nわたし、どうすればいいのぉ～っ", "", "vo_empress_130101_001", "vo_empress_130101_001", 4, 130101);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 326, 5, 1, "ワカナ", "きっと、長期戦になりますよね…\nあ、あの…ご飯、食べませんか？\nお腹が空くといけないと思って、\n作ってきたので…よろしければっ", "", "vo_empress_130101_002", "vo_empress_130101_002", 4, 130101);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 2, "", 327, 5, 1, "ワカナ", "む…むりっ！　無理ですよ～っ！\nあんなおっきいドラゴンなんて、\n勝てるわけないじゃないですかっ\nに、逃げちゃいましょ、ねっ…！？", "", "vo_empress_130101_003", "vo_empress_130101_003", 4, 130103);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (130101, 3, "", 328, 5, 1, "ワカナ", "と、盗られるぐらいなら盗るのが\n【バンディ・シスターズ】流ですっ\n騎士さん、わたしたちの未来を\n掴み取りにいきましょう…っ！", "", "vo_empress_130101_004", "vo_empress_130101_004", 4, 130102);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 329, 5, 1, "フブキ", "だる～、ささっと片付けてきてよ～\nムリ？　知ってる～だってザコザコ\nお兄さんだもんね♪　しょーがない\n助けてあげよっかな～？きゃはは♡", "", "vo_empress_130201_001", "vo_empress_130201_001", 4, 130201);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 330, 5, 1, "フブキ", "あの陰気ダサダサメガネさー、\n仲間集めてチョーシ乗ってねー？\nザコは何匹集まったってザコだって\nフブキちゃんが教えてあげまーす♪", "", "vo_empress_130201_002", "vo_empress_130201_002", 4, 130201);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 2, "", 331, 5, 1, "フブキ", "ふぇぇ…まじムリ、アイツムリ～！\n全然ラスボスってカンジじゃん！？\nぼくお家かえるぅ～っ！\nお兄さんも一緒にかえろっ、ねっ？", "", "vo_empress_130201_003", "vo_empress_130201_003", 4, 130203);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (130201, 3, "", 332, 5, 1, "フブキ", "お兄さん、やる気漲っちゃってる？\nだよねー、世界が滅んじゃったら\nぼくとも永遠のお別れなんだし？\n必死になるのもトーゼンっしょ～♡", "", "vo_empress_130201_004", "vo_empress_130201_004", 4, 130202);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 333, 5, 1, "クルル", "はわっ！？　すっごくすっごく\n悪そうな人達いっぱいですますぅ！\nかばばん君、警備員モードです！\nぴっぴーーーー！", "", "vo_empress_130901_001", "vo_empress_130901_001", 4, 130901);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 334, 5, 1, "クルル", "この戦いが終わったら、みなさんと\nパークで凱旋パレードですぅ♪\n…ふぇっ？\n気が早いですますか？", "", "vo_empress_130901_002", "vo_empress_130901_002", 4, 130901);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 2, "", 335, 5, 1, "クルル", "はわわっ！　幻境竜后さん、\n強そうすぎですっ…でもっ！\nやっと再建したパークも世界も\nぜったい壊させないですよ～っ！", "", "vo_empress_130901_003", "vo_empress_130901_003", 4, 130903);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (130901, 3, "", 336, 5, 1, "クルル", "ヒーローさんのこと、\nクルルの全部でお助けしますです！\nジオ・テオゴニアでも、どんな世界\nでも…ずっと、ず～っとですっ！", "", "vo_empress_130901_004", "vo_empress_130901_004", 4, 130902);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 337, 5, 1, "ルイズマリー", "なっなんなのよこいつらっ！\nダーリンとの恋路を邪魔する気…？\nそんなことさせないわ…だって、\n二人の恋はエターナルですからっ！", "", "vo_empress_132301_001", "vo_empress_132301_001", 4, 132301);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 338, 5, 1, "ルイズマリー", "愛情×愛情＝無限大…\n遂に錬金術の神髄に辿り着いたわ…\nさあ…お見舞いしてやりましょう！\n私とダーリンの究極錬成をっ！", "", "vo_empress_132301_002", "vo_empress_132301_002", 4, 132301);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 2, "", 339, 5, 1, "ルイズマリー", "あ、あなたがどんなに強くても、\n私は逃げないわ！　ダーリンに\nちょっかいかける奴は絶対に\n許さないって決めてるから…っ！！", "", "vo_empress_132301_003", "vo_empress_132301_003", 4, 132303);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (132301, 3, "", 340, 5, 1, "ルイズマリー", "悪いけど速攻で終わらせちゃうわ！\n早く帰ってダーリンと心行くまで\n破廉恥な乳繰り合い…じゃなくて！\n愛を確かめ合うんだからっ！", "", "vo_empress_132301_004", "vo_empress_132301_004", 4, 132302);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 341, 5, 1, "イロハ", "わわっ、敵がいっぱい！\nこれがクワガタだったら最高…よし\n新種のクワガタって事にしちゃお！\nあははっ！　待て待て～っ！！", "", "vo_empress_132401_001", "vo_empress_132401_001", 4, 132401);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 342, 5, 1, "イロハ", "あはは、まだまだ出てくるね～！\nなら新しい技いっぱい\n試しちゃおっか…さあ、いくよ！\n──イスルギ流奥義っ！！", "", "vo_empress_132401_002", "vo_empress_132401_002", 4, 132401);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 2, "", 343, 5, 1, "イロハ", "あのおねーさんもなかなか良いツノ\n持ってるねえ♪　イロハが勝ったら\nルイちゃんと二人でクワガタ相撲\nごっこやってもらおっと！", "", "vo_empress_132401_003", "vo_empress_132401_003", 4, 132401);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (132401, 3, "", 344, 5, 1, "イロハ", "おねーさんがどんなに強くたって\nイロハは絶対に負けない！\nおじちゃんが見ててくれてる時の\nイロハは、サイキョーなんだから！", "", "vo_empress_132401_004", "vo_empress_132401_004", 4, 132402);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 345, 5, 1, "ソノ", "いや無理無理、戦いとか苦手過ぎる\n…でも君となら、奇跡起こせるかも\n…うわやば、今の忘れて\n若者みたいなこと言っちゃったよ…", "", "vo_empress_132501_001", "vo_empress_132501_001", 4, 132501);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 346, 5, 1, "ソノ", "敵、まだいっぱいいるじゃん…\nはあ…残業したくないけど頑張るか\n全部終わったら君からのマッサージ\n期待しとくから、ね", "", "vo_empress_132501_002", "vo_empress_132501_002", 4, 132501);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 2, "", 347, 5, 1, "ソノ", "はあ…はあ…幻境竜后だっけ？\nルイちゃんの錬金術より\n出鱈目な強さだね…！\nでもまだまだ諦めない…いくよ！", "", "vo_empress_132501_003", "vo_empress_132501_003", 4, 132503);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (132501, 3, "", 348, 5, 1, "ソノ", "こんなに強い敵が相手でも\n諦めなきゃ勝てるんだって\n教えてくれたのは君だよ\nふふ…ありがとね、若者♪", "", "vo_empress_132501_004", "vo_empress_132501_004", 4, 132502);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 349, 5, 1, "グレイス", "うーわ。あっちもこっちも\nボス級だらけじゃないですか\nま、ヴァイオレット姫には\n指一本触れさせませんけどね", "", "vo_empress_133001_001", "vo_empress_133001_001", 4, 133001);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 4001, 10000, 350, 3, 1, "グレイス", "リーザ…今度こそ、決着の時ね\nいくら頭数を揃えても私は…いえ\n私と騎士氏は絶対に負けないわ\nこの槍で、冥界に送り返してあげる", 1, "vo_empress_133001_002", "vo_empress_133001_002", 4, 133003);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 2, "", 351, 5, 1, "グレイス", "ぐっ…圧倒的ですね『幻境竜后』\nですが…決してあきらめません\n私には、生きていてほしい人が\nたくさんいますので…！", "", "vo_empress_133001_003", "vo_empress_133001_003", 4, 133003);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (133001, 3, "", 352, 5, 1, "グレイス", "とてつもない強敵を前にしてるのに\nまるで恐怖心を感じません…\n…恋とは、心霊現象よりも\n不思議なものらしいですよ", "", "vo_empress_133001_004", "vo_empress_133001_004", 4, 133002);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 353, 5, 1, "ヴァイオレット", "恐るべき方々ばかりです…\nですがわたくしは絶対に退きません\nジオ・ニヴルヘルの姫として\nこの世界を守ると決めたのです！", "", "vo_empress_133101_001", "vo_empress_133101_001", 4, 133101);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 4001, 10000, 354, 3, 1, "ヴァイオレット", "リーザ…どうしてもわたくしたちの\n前に立ちはだかるというのですね\nならばわたくしも覚悟を決めました\nこの手であなたを、倒します…！", 1, "vo_empress_133101_002", "vo_empress_133101_002", 4, 133101);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 2, "", 355, 5, 1, "ヴァイオレット", "これが、彼女の本気の力…！\n異質で…故に、とても寂しい…\n本当の意味で彼女に届く声が、\nこの世界に存在するのでしょうか…", "", "vo_empress_133101_003", "vo_empress_133101_003", 4, 133103);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (133101, 3, "", 356, 5, 1, "ヴァイオレット", "あなたとの「繋がり」がある限り\n死が牙を剥くことはありません\n手を取り合い、共に参りましょう\nわたくしたちの未来のために！", "", "vo_empress_133101_004", "vo_empress_133101_004", 4, 133102);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 357, 5, 1, "メドゥーサ", "フンっ、次から次へと…！　なら\n思う存分、大暴れしてやるから♪\nやっちゃうわよ、メドゥシアナ！\nアンタも！！", "", "vo_empress_133601_001", "vo_empress_133601_001", 4, 133601);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 358, 5, 1, "メドゥーサ", "どこの誰だか知らないけれど、\nアタシの魔眼でまとめて石に…って\nきゃああああ！　こんなバケモン級\nなら先に教えときなさいよ～っ！", "", "vo_empress_133601_002", "vo_empress_133601_002", 4, 133601);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 2, "", 359, 5, 1, "メドゥーサ", "な…なんなの、アイツの『眼』…\nでもねっ、アタシはメドゥーサ\nゴルゴーンの、お姉ちゃんの妹よ！\n睨みあいで負けるわけがないわ！", "", "vo_empress_133601_003", "vo_empress_133601_003", 4, 133603);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (133601, 3, "", 360, 5, 1, "メドゥーサ", "知ってる？　蛇って執念深いのよ\nこの『眼』で見つけてやったわ\n幻境竜后、アンタが一番恐れること\nアタシとこいつが手をつなぐこと！", "", "vo_empress_133601_004", "vo_empress_133601_004", 4, 133602);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 361, 5, 1, "ホウオウ", "この大地と大空を守るため、\n人の子らだけに任せてはおけません\n鳳凰のはばたきで、その野望ごと\n跡形もなく吹き飛ばしましょう！", "", "vo_empress_134701_001", "vo_empress_134701_001", 4, 134701);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 362, 5, 1, "ホウオウ", "さあ皆さん、ここが正念場です！\n私がいれば楽勝圧勝間違いなし！\n…えっ？　私が先頭？　えーと…\nあっちょっと待って押さないで！", "", "vo_empress_134701_002", "vo_empress_134701_002", 4, 134701);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 2, "", 363, 5, 1, "ホウオウ", "羽が散って、ちっ、力が…\n幻境竜后、やるではないですか…\nしかし、私も不死鳥と呼ばれた身…\nただでやられは…ぴ、ぴよぉぉ～…", "", "vo_empress_134701_003", "vo_empress_134701_003", 4, 134703);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (134701, 3, "", 364, 5, 1, "ホウオウ", "幻境竜后、でしたか？\nあなたも運のない方ですね\n今の私は輪廻史上最強の鳳凰\nその鱗一つ残さず焼き尽くします！", "", "vo_empress_134701_004", "vo_empress_134701_004", 4, 134702);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 365, 5, 1, "カノン", "ヲ～ッホッホ！　どいつもこいつも\n大層なおツラ構えしてますけどぉ？\nあたくし様の敵じゃありませんわ！\nほら馬ボーン！　お強化なさいな！", "", "vo_empress_134901_001", "vo_empress_134901_001", 4, 134901);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 366, 5, 1, "カノン", "いってぇ～ですわ！　あたくし様の\nお美しいお肌を傷つけましたわね！\nまとめてお成敗して差し上げますわ\nついてらっしゃいな！　馬ボーン！", "", "vo_empress_134901_002", "vo_empress_134901_002", 4, 134901);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 2, "", 367, 5, 1, "カノン", "なんてタマですの…アースハイドラ\nよりデカいなんて聞いてませんわ！\nでも…ここでお尻尾巻いて逃げる\nなら、死んだ方がマシですわ…！", "", "vo_empress_134901_003", "vo_empress_134901_003", 4, 134903);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (134901, 3, "", 368, 5, 1, "カノン", "幻境竜后とやら、お覚悟なさいな\nあたくしと馬ボーンの前に立つなど\n100億万年お早いですわ！\n華麗にお成敗して差し上げますわ♪", "", "vo_empress_134901_004", "vo_empress_134901_004", 4, 134902);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 369, 5, 1, "アイラ", "来たね、お姉さんの出番ってやつ♪\nキミと一緒に戦えるなんて、あたし\nテンション最高潮だよ！　あははっ\nさ、思いっきり暴れちゃおっか！", "", "vo_empress_135501_001", "vo_empress_135501_001", 4, 135501);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 4005, 10000, 370, 3, 1, "アイラ", "あれが…覇瞳皇帝のオリジナルだね\nま、関係ないや。本物でも偽物でも\n今度こそ決着つけてあげるから！\nお姉さんの拳…燃え盛ってるよー！", 1, "vo_empress_135501_002", "vo_empress_135501_002", 4, 135501);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 2, "", 371, 5, 1, "アイラ", "幻境竜后…とんでもない相手だね\nあたしの拳だって届かないかも…\nそれでも、燃え尽きるまで戦うよ\nキミが信じてくれてる限り、ね！", "", "vo_empress_135501_003", "vo_empress_135501_003", 4, 135503);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (135501, 3, "", 372, 5, 1, "アイラ", "キミがいれば怖いものなし！\nお姉さん今、燃えに燃えてるよっ\n太陽より熱く燃える拳で…\n全部まとめてぶっ飛ばす！", "", "vo_empress_135501_004", "vo_empress_135501_004", 4, 135502);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 373, 5, 1, "シナツ", "どれほどの逆風の中にいても、\n諦めてはならない…そうだろう？\nかつて私が、他でもないキミたちに\nそう教えてもらったんだ…", "", "vo_empress_135601_001", "vo_empress_135601_001", 4, 135601);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 374, 5, 1, "シナツ", "私はこの世界の人々と出会い、\n失ったはずの希望を見つけられた\n今度は私が、皆に希望を届ける番だ\nこの刃、存分に振るわせてくれ", "", "vo_empress_135601_002", "vo_empress_135601_002", 4, 135601);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 2, "", 375, 5, 1, "シナツ", "幻境竜后…私たちの世界を創造し、\nそして滅ぼそうとした張本人か…！\nその力がどんなに強大だとしても…\n私は…絶対に逃げたりなどしない！", "", "vo_empress_135601_003", "vo_empress_135601_003", 4, 135603);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (135601, 3, "", 376, 5, 1, "シナツ", "私の刃に、もはや一片の曇りもない\n皆と生きる未来を守り抜くために\n戦いつづける…ただそれだけだ\n─道を阻む者は全て斬り伏せる！", "", "vo_empress_135601_004", "vo_empress_135601_004", 4, 135602);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 4001, 10000, 377, 3, 1, "ユキノ", "リ、リ、リーザちゃ…！\nリーザちゃはあてのこと、ヘタレの\nホジナシって思ってっかもだけど…\n前より成長したとこ、見せっから！", 1, "vo_empress_135801_001", "vo_empress_135801_001", 4, 135801);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 378, 5, 1, "ユキノ", "田舎者で世間知らずなあてだけど…\n騎士さと一緒にいろんなとこ行って\n大切な思い出、いっぱいできたよ…\nだから守りてぇんだ、この世界…！", "", "vo_empress_135801_002", "vo_empress_135801_002", 4, 135801);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 2, "", 379, 5, 1, "ユキノ", "あ、あても、ちったぁでけぇけど…\n幻境竜后、で、でっかすぎ…！\nそ、それに竜まで…！　炎浴びたら\nあて、溶けちまうよぅ…！", "", "vo_empress_135801_003", "vo_empress_135801_003", 4, 135803);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (135801, 3, "", 380, 5, 1, "ユキノ", "「あてなんか」なんて、考えね…\n騎士さが信じてくれるなら、\nあてだって自分のこと、信じるよ\nあてと騎士さなら大丈夫、って…！", "", "vo_empress_135801_004", "vo_empress_135801_004", 4, 135802);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 4001, 10000, 381, 3, 1, "サツキ", "リザ公…手前ェどの面下げて\n俺の前に出てきやがった\nまァいいさ、何聞いても今更だ\nここで落とし前つけてもらうぜ", 1, "vo_empress_135901_001", "vo_empress_135901_001", 4, 135903);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 382, 5, 1, "サツキ", "いつ死んでもいいなんて\nもう思っちゃいねぇさ\nこの悪玉どもより、図太くしぶとく\n生き抜いてやろうじゃねぇか", "", "vo_empress_135901_002", "vo_empress_135901_002", 4, 135901);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 2, "", 383, 5, 1, "サツキ", "あれが幻境竜后か…\nハンパじゃねェや\nしゃあねぇ、こうなりゃ一丁\n死に花咲かすとするか", "", "vo_empress_135901_003", "vo_empress_135901_003", 4, 135901);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (135901, 3, "", 384, 5, 1, "サツキ", "世界だの未来だの現実だの…\n重いったらありゃしねぇぜ\n潰れるなよ、騎士公\n俺も一緒に担いでやっからさ", "", "vo_empress_135901_004", "vo_empress_135901_004", 4, 135902);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 385, 5, 1, "アラクネ", "騎士さま、どうかご安心を…\nどれだけ厳しい運命が待って\nいたとしても…あなたのことは、\nわたしの糸が必ずお守りします", "", "vo_empress_136001_001", "vo_empress_136001_001", 4, 136001);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 4003, 10000, 386, 3, 1, "アラクネ", "…？　あの金髪の女性、なんだか\n見覚えあるような気が…いえ\n騎士さまの敵は、わたしの敵です\nそれだけです…", 1, "vo_empress_136001_002", "vo_empress_136001_002", 4, 136001);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 2, "", 387, 5, 1, "アラクネ", "あれが幻境竜后さま…\nなんという恐るべき力\n…騎士さま、わたしの後ろに\n一度くらいは、庇えるはずです…", "", "vo_empress_136001_003", "vo_empress_136001_003", 4, 136003);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (136001, 3, "", 388, 5, 1, "アラクネ", "騎士さまという光が、わたしに力を\n与えてくれるのです。ともに未来を\n歩むためにも…この戦いに\n必ず勝ちましょう、騎士さま", "", "vo_empress_136001_004", "vo_empress_136001_004", 4, 136002);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 389, 5, 1, "ナーナ", "強そうな敵さんがいっぱい～っ！？\nこーなったら、ウルトラとっておき\nドーナツ！　ちょっと湿気てるけど\n…はい騎士ちゃん、あーんっ♪", "", "vo_empress_136201_001", "vo_empress_136201_001", 4, 136201);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 390, 5, 1, "ナーナ", "ナーナだって頑張れるんだよっ！\n騎士ちゃんに、そう教わったもん！\nだから、すごく怖いけど…でもっ…\nナーナ、逃げたりしないよぉっ！", "", "vo_empress_136201_002", "vo_empress_136201_002", 4, 136201);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 2, "", 391, 5, 1, "ナーナ", "うぅ…あ、足が震えてきちゃった…\nでも動かなきゃ、戦わなきゃっ…\nわかってるのに、でもでもぉ…\nうえぇぇん、やっぱり怖いぃぃ！", "", "vo_empress_136201_003", "vo_empress_136201_003", 4, 136201);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (136201, 3, "", 392, 5, 1, "ナーナ", "今のナーナはよわよわウサギじゃ\nないんだよ。騎士ちゃんのためなら\nどんな敵さんだってやっつけちゃう\nつよつよウサギなんだから！", "", "vo_empress_136201_004", "vo_empress_136201_004", 4, 136202);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 4001, 10000, 393, 3, 1, "ルルィ", "リーザ姉しゃまが裏切ったなんて\nあたち、信じたくないでしゅ…！\nだから直接聞きにいきましゅ\n吸盤ぜんぶで捕まえてでも…！", 1, "vo_empress_136901_001", "vo_empress_136901_001", 4, 136903);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 394, 5, 1, "ルルィ", "姫姉しゃまも騎士しゃんも\nみなしゃん戦ってるんでしゅ\nあたちだって負けましぇん！\n一生懸命がんばりましゅ～！", "", "vo_empress_136901_002", "vo_empress_136901_002", 4, 136901);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 2, "", 395, 5, 1, "ルルィ", "あ、あの方、こわいでしゅ…！\n丸呑みにされちゃいそうでしゅっ\nうじゅ…がんばりたいでしゅが…\n震えが止まらないでしゅ…！", "", "vo_empress_136901_003", "vo_empress_136901_003", 4, 136903);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (136901, 3, "", 396, 5, 1, "ルルィ", "あたちは強くないでしゅけど\n騎士しゃんとの約束がありましゅ\nだから誰にも負けましぇん！\nいっちょに、守りましゅよ！", "", "vo_empress_136901_004", "vo_empress_136901_004", 4, 136902);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 397, 5, 1, "リリ", "これから挑む敵がどれだけ強いと\nしても、勇往邁進していきます\nですからこの戦いでも、兄様の\nおそばで戦わせてくださいませ", "", "vo_empress_139501_001", "vo_empress_139501_001", 4, 139501);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 4002, 10000, 398, 3, 1, "リリ", "幻境竜后の手先、アルシャト…！\nリアさんやヴルム様を陥れた貴方を\n決して許す訳には参りません！\n不倶戴天─ここで成敗致します！", 1, "vo_empress_139501_002", "vo_empress_139501_002", 4, 139503);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 2, "", 399, 5, 1, "リリ", "幻境竜后の力…これほどまでに\n強力無比だとは…で、ですが…\n何があろうとわたくしは兄様を\nお守りします…命に代えても、必ず", "", "vo_empress_139501_003", "vo_empress_139501_003", 4, 139503);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (125801, 3, "", 400, 5, 1, "リリ", "兄様への想いと、重ねてきた大切な\n時間が、たくさんの勇気と限界を\n超える奇跡をくれました。全ての人\nを救うため、参りましょう兄様…！", "", "vo_empress_139501_004", "vo_empress_139501_004", 4, 139502);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 401, 5, 1, "クリア", "お兄さん、もし怪我しちゃっても\nすぐに治癒しますからご安心を！\nわたし決めましたから…もう二度と\n自分自身から逃げないって…！", "", "vo_empress_139601_001", "vo_empress_139601_001", 4, 139603);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 4002, 10000, 402, 3, 1, "クリア", "…アルシャトさん…\n謝ったって許してあげませんよ？\nあなたの前では、わたしちょっと\nいい子じゃいられませんから…っ！", 1, "vo_empress_139601_002", "vo_empress_139601_002", 4, 139603);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 2, "", 403, 5, 1, "クリア", "うぅっ…これが本気の幻境竜后…！\n…こんなの勝てっこありませんよ…\n…せめてお兄さんだけでも…なんて\n最後まで…諦めませんからっ…！", "", "vo_empress_139601_003", "vo_empress_139601_003", 4, 139603);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (126001, 3, "", 404, 5, 1, "クリア", "お兄さんの気持ちが胸に溢れて…\nあ、えへへ…なんだか視界が\n滲んできちゃいました…♪\nわたしはもう、負けませんよ…っ！", "", "vo_empress_139601_004", "vo_empress_139601_004", 4, 139601);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 405, 5, 1, "プレシア", "てき、いっぱい、しかも、つよすぎ\nけど、まけないよ\nお兄のほっぺ、たべて\nふるぱわー", "", "vo_empress_139701_001", "vo_empress_139701_001", 4, 139701);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 1, "", 406, 5, 1, "プレシア", "ん\nまだまだ、いける\nお兄、パパ、なかま、いる\nむしゃぶるい", "", "vo_empress_139701_002", "vo_empress_139701_002", 4, 139701);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (0, 2, "", 407, 5, 1, "プレシア", "しょうり、みえない\nせいぎ、まもれない\nそんなの、いや\nあきらめないよ、さいごまで", "", "vo_empress_139701_003", "vo_empress_139701_003", 4, 139703);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (126101, 3, "", 408, 5, 1, "プレシア", "て、つなぐ\nせいめいりょく、たかまる\nぜったいしょうり！", "", "vo_empress_139701_004", "vo_empress_139701_004", 4, 139702);
INSERT INTO `v1_8fd482fc6e363f80824716a02582e1f40495f4feecb41268629ee5b4204b9f1f` VALUES (140301, 3, "", 409, 5, 1, "ティア", "七冠、幻境竜后──LoAの開発者\nあんたにコワいコト教えてあげるわ\n些細なバグと思って放置したら\nゲームを壊すこともあるってね…♪", "", "vo_empress_140301_004", "vo_empress_140301_004", 4, 140301);
